	local function crc32_proto(data)
		local crc2 = 4294967295
		for index = 1, #data do
			crc2 = bit32.bxor(
				crcTable[bit32.band(bit32.bxor(crc2, string.byte(data, index)), 255) + 1],
				bit32.rshift(crc2, 8)
			)
		end
		return (bit32.bxor(crc2, 4294967295))
	end

	local function adler32_proto(data)
		local a = 1
