	local function applyMaterialSpec(self_, spec)
		self_._spec = spec
		if spec == nil then
			local snapshots = self_._snapshots
			local key = nil
			while true do
				local snapshot
				key, snapshot = snapshots(nil, key)
				if key == nil then
