	local function onItemAdded_proto(item)
		local index = table.find(inventory._localFighterState:GetItems(), item)
		if not index then
			index = #inventory._items
		end
		local added = inventory:AddItem(item, index)
		reindexItems()
		if added ~= nil then
			inventory.itemAdded:Fire(added)
		end
	end

	local function onItemRemoved_proto(item)
		local entry, index
		index, entry = inventory:GetByInner(item)
		if not (index == nil or entry == nil) then
			table.remove(inventory._items, index)
			local objectId = entry.objectId
			local removed = inventory._byObjectId[objectId]
			inventory._byObjectId[objectId] = nil
			inventory._byName[item.Name] = nil
			inventory._byInner[item] = nil
			reindexItems()
			inventory.itemRemoved:Fire(removed)
			if removed ~= nil then
				removed.item:Destroy()
			end
		end
	end

	local function onEquippedItemChanged_proto(item)
		if item == nil then
			inventory.equippedItemChanged:Fire(nil)
		else
			inventory.equippedItemChanged:Fire(inventory._byInner[item])
		end
	end

	local function reindexItems_proto()
		for index, item in inventory._localFighterState:GetItems() do
			local itemIndex = inventory:GetByInner(item)
			if itemIndex ~= nil then
				inventory._items[itemIndex].item.index = index
			end
		end
	end

	local function bindFighterItems(inventory)
		for slot, initialItem in inventory._localFighterState:GetItems() do
			inventory:AddItem(initialItem, slot)
		end

		local function reindexItems()
			for index, item in inventory._localFighterState:GetItems() do
				local itemIndex = inventory:GetByInner(item)
				if itemIndex ~= nil then
					inventory._items[itemIndex].item.index = index
				end
			end
		end

		local function onItemAdded(item)
			local index = table.find(inventory._localFighterState:GetItems(), item)
			if not index then
				index = #inventory._items
			end
			local added = inventory:AddItem(item, index)
			reindexItems()
			if added ~= nil then
				inventory.itemAdded:Fire(added)
			end
		end

		inventory._trove:Add(inventory._localFighterState:OnItemAddedSignal(onItemAdded))

		local function onItemRemoved(item)
			local entry, index
			index, entry = inventory:GetByInner(item)
			if not (index == nil or entry == nil) then
				table.remove(inventory._items, index)
				local objectId = entry.objectId
				local removed = inventory._byObjectId[objectId]
				inventory._byObjectId[objectId] = nil
				inventory._byName[item.Name] = nil
				inventory._byInner[item] = nil
				reindexItems()
				inventory.itemRemoved:Fire(removed)
				if removed ~= nil then
					removed.item:Destroy()
				end
			end
		end

		inventory._trove:Add(inventory._localFighterState:OnItemRemovedSignal(onItemRemoved))

		local function onEquippedItemChanged(item)
			if item == nil then
				inventory.equippedItemChanged:Fire(nil)
			else
				inventory.equippedItemChanged:Fire(inventory._byInner[item])
			end
		end

		inventory._trove:Add(inventory._localFighterState:OnEquippedItemChangedSignal(onEquippedItemChanged))
		onEquippedItemChanged(inventory._localFighterState:GetEquippedItem())
	end

