	local function setupWaypointsCreation(recorder, trove, contexts)
		local function destroyWaypoints()
			local waypoints = recorder._waypoints
			if waypoints ~= nil then
				recorder._waypoints = nil
				waypoints:Destroy()
			end
		end

		local function refreshWaypoints()
			if not settings.data.MovementRecorder.Enabled then
				destroyWaypoints()
				return
			end
			local anchor = recorder._currentMap:GetAnchor()
			if anchor == nil then
				destroyWaypoints()
				return
			end
			local localState = recorder._duelers.localState
			if localState == nil then
				destroyWaypoints()
				return
			end
			local mapName = localState:GetMapName()
			if mapName == nil then
				destroyWaypoints()
				return
			end
			if recorder._waypoints == nil then
				recorder._waypoints = Waypoints.new(recorder._persistence, contexts, mapName, anchor)
			end
		end

		local mapTrove = trove:Extend()

		local function onMapChanged()
			destroyWaypoints()
			refreshWaypoints()
		end

		local function watchMapChanges(localState)
			mapTrove:Clean()
			mapTrove:Connect(localState.mapChanged, onMapChanged)
		end

		local function onLocalStateSet(localState)
			watchMapChanges(localState)
			refreshWaypoints()
		end

		trove:Connect(recorder._duelers.onLocalStateSet, onLocalStateSet)

		local function onLocalStateRemoved()
			mapTrove:Clean()
