	local function getLookAngles(anchorCFrame, nextAction)
		local key = nil
		while true do
			local entry
			key, entry = nextAction(nil, key)
			if key == nil then
				break
			end
			local action = entry.action
			if action.kind == "Look" then
				local yaw, pitch
				pitch, yaw = (anchorCFrame * action.cframe):ToOrientation()
				return (Vector2.new(pitch, yaw))
			end
		end
		return nil
	end

