	local function checkVisible_proto(checker, origin, part, model)
		local isPoint
		isPoint = typeof(origin) == "Vector3"
		local inner = checker._playerContext.inner
		if not inner then
			return false, nil
		end
		if not isPoint then
			local cached = checker._visible[origin][part]
			if cached ~= nil then
				return cached, checker._result[origin][part]
			end
		end
		local originPos = nil
		if isPoint then
			originPos = origin
		elseif origin == "ServerOrigin" then
			local headOrigin = inner.characterController:GetServerHeadOrigin()
			if headOrigin == nil then
				return false, nil
			end
			originPos = headOrigin.Position
		elseif origin == "Camera" then
			originPos = workspace.CurrentCamera.CFrame.Position
		end
		local params = checker._worldInclude:GetParams()
		if not params then
			return false, nil
		end
		local hit = workspace:Raycast(originPos, part.Position - originPos, params)
		local isVisible = false
		if hit ~= nil then
			isVisible = hit.Instance == part
			if not isVisible then
				isVisible = not (model == nil)
				if isVisible then
					isVisible = model:IsAncestorOf(hit.Instance)
				end
			end
		end
		if not isPoint then
			local visibleCache = checker._visible[origin]
			local resultCache = checker._result[origin]
			visibleCache[part] = isVisible
			resultCache[part] = hit
		end
		return isVisible, hit
	end

