			end
			self._model = nil
			if model ~= nil then
				local clone = model:Clone()
				if clone ~= nil then
					clone.Parent = self._worldModel
					self._model = clone
					local radius, center
					center, radius = getBounds(clone)
					self._modelCenter = center
					self._modelRadius = radius
