		function ViewportPreview:SetDistance(multiplier)
			self._distanceMultiplier = math.max(0.1, multiplier)
			updateCamera(self)
			return self
		end

		function ViewportPreview:SetRotation(rotation)
			self._rotation = rotation
			updateCamera(self)
			return self
