			trove:Connect(settings:GetPropertyChangedSignal(enabledKey), notify)
			trove:Connect(settings:GetPropertyChangedSignal(modeKey), notify)
			trove:Connect(settings:GetPropertyChangedSignal(activeKey), notify)
