	local function moveInList(list, value, delta)
		local index = table.find(list, value)
		if index == nil then
			return false
		end
		local target = math.clamp(index + delta, 1, #list)
		if target == index then
			return false
		end
		table.remove(list, index)
		table.insert(list, target, value)
		return true
	end

