		end
		resolvedOptions.maxBranches = maxBranches
		local branches = {
			_trove = Trove.new(),
			_host = host,
			_trunk = trunk,
			_bolts = {},
			_startT = os.clock(),
			_holdTime = holdTime,
			_dissipateTime = dissipateTime,
