	local function shouldFire_proto(self_, fire, duration)
		local now = os.clock()
		local lockedUntil = self_._lockedUntil
		local shouldFire
		shouldFire = not (lockedUntil == nil)
		if shouldFire then
			shouldFire = now < lockedUntil
		end
		if fire then
			self_._lockedUntil = now + duration
		end
		if not shouldFire then
			shouldFire = fire
		end
		return shouldFire
	end

