	local function parseDsn(dsn)
		local projectId, host, key
		key, host, projectId = dsn:match("^https?://([^@]+)@([^/]+)/(.+)$")
		local parsed
		parsed = not (key == nil)
		if parsed then
			parsed = not (host == nil)
		end
		if parsed then
			parsed = not (projectId == nil)
		end
		if parsed then
			parsed = { key = key, host = host, projectId = projectId }
		end
		if not parsed then
			parsed = nil
		end
		return parsed
	end

