				entry = {}
				self._proposed[item] = entry
			end
			if entry[cosmeticType] == value then
				return false
			end
			entry[cosmeticType] = value
			if next(entry) == nil then
				self._proposed[item] = nil
			end
			self.changed:Fire()
			return true
		end

		function ProposedEquips:ExportState()
