			part.Name = "WeatherEmitter"
			part.Anchored = true
			part.CanCollide = false
			part.CanQuery = false
			part.CanTouch = false
			part.Transparency = 1
			part.Size = Vector3.new(140, 1, 140)
			part.Parent = Workspace
			trove:Add(part)
