			self._hitFlash:Update(dt)
			local i = #self._chams - -1
			while true do
				i = i + -1
				if not (1 <= i) then
					break
				end
				if not self._chams[i]:Step(dt) then
					table.remove(self._chams, i)
				end
			end
		end

		function PlayerHitFeedback:Destroy()
			local chams = self._chams
			local index = nil
			while true do
				local cham
				index, cham = chams(nil, index)
				if index == nil then
