	local function loadBitOps()
		local xorTable = {}
		local andTable = {}
		for hi = 0, 15 do
			for lo = 0, 15 do
				local xorResult = 0
				local andResult = 0
				local bit = 1
				local i = 0
				local bRest = lo
				local aRest = hi
				while true do
					i = i + 1
					if not (i <= 4) then
						break
					end
					local aBit = aRest % 2
					local bBit = bRest % 2
					if aBit ~= bBit then
						xorResult = xorResult + bit
					end
					if aBit == 1 and bBit == 1 then
						andResult = andResult + bit
					end
					aRest = math.floor(aRest / 2)
					bRest = math.floor(bRest / 2)
					bit = bit * 2
				end
				xorTable[hi * 16 + lo] = xorResult
