	local function resolveEffective_proto(manager, state, excludedLayers)
		local effective = {}
		local winnerPriorities = emptySelection()
		local nextCosmeticType = CosmeticTypes.item
		local index = nil
		while true do
			local cosmeticType
			index, cosmeticType = nextCosmeticType(nil, index)
			if index == nil then
				break
			end
			local capturedType = cosmeticType

			local function getSlotValue(selection)
				return (selectionUtil.getSelectionValue(selection, capturedType))
			end

			local function isLayerIncluded(priority)
				if not (excludedLayers == nil or not excludedLayers[priority]) then
					return false
				end
				local active
				active = manager._activeLayers[priority] == true
				return active
			end

			local value, winnerPriority
			winnerPriority, value = priorityLayers.resolveHighestPriority(state.layers, getSlotValue, isLayerIncluded)
-- [removed 2 line(s) containing unnamed identifiers]
		end
		local result = { selection = effective, winnerPriorities = winnerPriorities }
