	local function loadCosmeticsTab()
-- [removed 10 line(s) containing unnamed identifiers]
		local playerAssets = findDescendant(
			cloneref(game:GetService("Players")).LocalPlayer,
			(table.create(2))
		)
		local wrapPreviewModel = findDescendant(playerAssets, (table.create(2)))
		local charmsFolder = findDescendant(playerAssets, "Charms")
		local tabIcons = {
			Cosmetics = "rbxassetid://128162112866809",
			General = "rbxassetid://89644754139307",
			Skins = "rbxassetid://97652569554326",
			Wraps = "rbxassetid://76631821212930",
			Charms = "rbxassetid://125353572203968",
			Finishers = "rbxassetid://82039875682356"
		}
		local defaultImage = "rbxassetid://89204837120267"

		local function getImage(name)
			local image = cosmeticImages.Images[name]
			if not image then
				image = defaultImage
			end
			return image
		end

		local function toChoiceValue(displayName)
			if displayName == nil or displayName == "Unselected" then
				return nil
			end
			if displayName == "None" then
				return "NONE_COSMETIC"
			end
			if displayName == "Random" then
				return "RANDOM_COSMETIC"
			end
			return displayName
		end

		local function toDisplayName(value)
			if value == "NONE_COSMETIC" then
				return "None"
			end
			if value == "RANDOM_COSMETIC" then
				return "Random"
			end
			if value == nil then
				return "Unselected"
			end
			return value
		end

		UDim2.fromOffset(50, 50)
		local specialItems = table.create(3)
		local alwaysShown = { Unselected = true, None = true, Random = true }

		local function makeFilter(query)
			if query == "" then
				return nil
			end

			local function filter(item, name)
				if alwaysShown[item.Name] then
					return true
				end
				local matches
				matches = not (fuzzyMatch(name, query) == nil)
				return matches
			end

			return filter
		end

		local function buildItemList(nextName, makeRenderer)
			local items = table.clone(specialItems)
			local index, renderer
			while true do
				local name
				index, name = nextName(nil, index)
				if index == nil then
					break
				end
				local _ = table.insert
				local entry = { Name = name, Image = getImage(name) }
				if makeRenderer then
					renderer = makeRenderer(name)
				else
					renderer = makeRenderer
				end
				entry.Render = renderer
				table.insert(items, entry)
			end
			return items
		end

		local previewCameraCFrame = CFrame.Angles(0, 3.490658503988659, 0) * CFrame.Angles(-0.2617993877991494, 0, 0) * CFrame.new(0, 0, 1)

		local function makeWrapPreview(wrapName)
			local function renderPreview(_, tile)
				tile.HideImage()
				local viewportFrame = Instance.new("ViewportFrame")
				viewportFrame.Size = UDim2.fromScale(1, 1)
				viewportFrame.Position = UDim2.fromScale(0.5, 0.5)
				viewportFrame.AnchorPoint = Vector2.new(0.5, 0.5)
				viewportFrame.BackgroundTransparency = 1
				viewportFrame.Parent = tile.Content
				local camera = Instance.new("Camera")
				camera.FieldOfView = 25
				camera.CFrame = previewCameraCFrame
				camera.Parent = viewportFrame
				viewportFrame.CurrentCamera = camera
				local model = wrapPreviewModel:Clone()
				model:PivotTo(CFrame.identity)
				local originals = wrapRenderer.recordOriginalProperties(model)
				wrapRenderer.applyWrap(originals, wrapName)
				model.Parent = viewportFrame
			end

			return renderPreview
		end

		local charmPitch = -0.2617993877991494

		local function makeCharmPreview(charmName)
			local function renderPreview(_, tile)
				local charmTemplate = charmsFolder:FindFirstChild(charmName)
				if charmTemplate == nil then
					return
				end
				tile.HideImage()
				local viewportFrame = Instance.new("ViewportFrame")
				viewportFrame.Size = UDim2.fromScale(1, 1)
				viewportFrame.Position = UDim2.fromScale(0.5, 0.5)
				viewportFrame.AnchorPoint = Vector2.new(0.5, 0.5)
				viewportFrame.BackgroundTransparency = 1
				viewportFrame.Parent = tile.Content
				local camera = Instance.new("Camera")
				camera.FieldOfView = 25
				camera.Parent = viewportFrame
				viewportFrame.CurrentCamera = camera
				local charm = charmTemplate:Clone()
				if charm:IsA("Model") then
					local primary = charm:FindFirstChild("Primary")
					if primary and primary:IsA("BasePart") then
						charm.PrimaryPart = primary
					end
					charm:PivotTo(CFrame.identity)
					local hook = charm:FindFirstChild("Hook")
					if hook then
						hook:Destroy()
					end
				end
				charm.Parent = viewportFrame
				camera.CFrame = CFrame.Angles(0, 3.62836073281, 0) * CFrame.Angles(charmPitch, 0, 0) * CFrame.new(0, 0, 0.3)
			end

			return renderPreview
		end

		local function buildRankCharmSection(app, grid)
			local AddSection95 = grid.AddSection
-- [removed 2 line(s) containing unnamed identifiers]
			local seasonOptions = {}
			local charmBySeasonLabel = {}
			local nextSeasonCharm = RankCharms.SEASON_CHARMS
			local index = nil
			while true do
				local seasonCharm
				index, seasonCharm = nextSeasonCharm(nil, index)
				if index == nil then
					break
				end
				local label = string.format(
					"Season %s (%s)",
					tostring(seasonCharm.version),
					tostring(seasonCharm.seasonName)
				)
				table.insert(seasonOptions, label)
				charmBySeasonLabel[label] = seasonCharm.charmName
			end
			local rankOptions = table.create(1)
			local nextRankName = RankCharms.RANK_NAMES
			local index2 = nil
			while true do
				local rankName
				index2, rankName = nextRankName(nil, index2)
				if index2 == nil then
					break
				end
				table.insert(rankOptions, rankName)
			end
			local AddDropdown84 = rankCharmOverrideSection.AddDropdown
			local seasonDropdownOptions = { Label = "Season", Options = seasonOptions, CloseOnSelect = true }
			local seasonDropdown = AddDropdown84(rankCharmOverrideSection, seasonDropdownOptions)
			local AddDropdown85 = rankCharmOverrideSection.AddDropdown
			local rankDropdownOptions = { Label = "Rank", Options = rankOptions, CloseOnSelect = true }
			local rankDropdown = AddDropdown85(rankCharmOverrideSection, rankDropdownOptions)
			local AddTextBox22 = rankCharmOverrideSection.AddTextBox
			local leaderboardRankOptionalEG1TextBoxOptions = { Label = "Leaderboard Rank (optional, e.g. 1)" }
			local leaderboardRankOptionalEG1TextBox = AddTextBox22(rankCharmOverrideSection, leaderboardRankOptionalEG1TextBoxOptions)

			local function getSelectedCharmName()
				local selected = seasonDropdown.Value
				local charmName
				charmName = not (selected == nil)
				charmName = charmName and charmBySeasonLabel[selected] or nil
				return charmName
			end

			local function parseLeaderboardRank()
				local trimmed = leaderboardRankOptionalEG1TextBox.Value:match("^%s*(.-)%s*$")
				if trimmed == nil or trimmed == "" then
					return nil
				end
				local rank = tonumber(trimmed)
				if rank == nil or rank < 1 then
					return nil
				end
				return (math.floor(rank))
			end

			local rankCharm = app.cosmetics:GetRankCharm()

			local function applyRankCharm(...)
				local charmName = getSelectedCharmName()
				if charmName == nil then
					return
				end
				local rank = rankDropdown.Value
				if not rank then
					rank = "Off"
				end
				if rank == "Off" then
					rankCharm:SetForSeason(charmName, nil, nil)
					return
				end
				rankCharm:SetForSeason(charmName, rank, parseLeaderboardRank())
			end

			local function syncRankCharmControls()
				local charmName = getSelectedCharmName()
				if charmName == nil then
					rankDropdown:Set("Off", true)
					leaderboardRankOptionalEG1TextBox:Set("", true)
					return
				end
				local leaderboardRank, rank
				rank, leaderboardRank = rankCharm:GetForSeason(charmName)
				local dropdown = rankDropdown
				local set = dropdown.Set
				if not rank then
					rank = "Off"
				end
				set(dropdown, rank, true)
				local textBox = leaderboardRankOptionalEG1TextBox
				local set2 = textBox.Set
				local text
				text = not (leaderboardRank == nil)
				text = text and tostring(leaderboardRank) or ""
				set2(textBox, text, true)
			end

			seasonDropdown:OnChanged(syncRankCharmControls)
			rankDropdown:OnChanged(applyRankCharm)
			leaderboardRankOptionalEG1TextBox:OnChanged(applyRankCharm)
			return syncRankCharmControls
		end

