				local selections = app.cosmetics:GetSkinChangerSelections(weapon)
				if selections == nil then
					skinPicker:Set("Unselected", true)
					wrapPicker:Set("Unselected", true)
					invertedToggle:Set(false, true)
					charmPicker:Set("Unselected", true)
					finisherPicker:Set("Unselected", true)
