			local enemies = registry.enemies
			local key = player
			repeat
				if isEnemy then
					isEnemy = entity
				end
			until not isEnemy
			enemies[key] = nil
			return
		end

		entity._trove:Connect(entity.enemyChanged, onEnemyChanged)
