	local function createSwatch(picker, parent, context)
		local textButton = Instance.new("TextButton")
		textButton.AnchorPoint = Vector2.new(1, 0.5)
		textButton.Position = UDim2.fromScale(1, 0.5)
		textButton.Size = UDim2.fromOffset(18, 18)
		textButton.BorderSizePixel = 0
		textButton.BackgroundColor3 = picker.Color
		textButton.Text = ""
		textButton.AutoButtonColor = false
		textButton.Parent = parent
		local uiCorner = Instance.new("UICorner")
		uiCorner.CornerRadius = UDim.new(0, 5)
		uiCorner.Parent = textButton
		local uiGradient = Instance.new("UIGradient")
		local isGradient
		isGradient = picker.Mode == "Gradient"
		uiGradient.Enabled = isGradient
		if picker.Mode == "Gradient" then
			uiGradient.Color = Stops.toSequence(picker.Stops)
		else
			uiGradient.Color = ColorSequence.new(picker.Color)
		end
		uiGradient.Parent = textButton
		local renderRefs = { Swatch = textButton, SwatchGradient = uiGradient }
		picker._rt = renderRefs
		picker._parentOverlay = context.ParentOverlay

		local function onSwatchClicked()
			if picker._panel == nil then
				openPopup(picker, textButton)
			end
			local popup = picker._popup
			if popup ~= nil then
				popup:Toggle()
			end
		end

		inputUtil.connectClick(context.Trove, textButton, onSwatchClicked)
		return textButton
	end

	local function setAnimationMode(picker, mode, silent)
		if picker.AnimationMode ~= mode then
			picker.AnimationMode = mode
			local panel = picker._panel
			if panel ~= nil then
				panel.SyncAnimation(mode, picker.AnimationSpeed)
			end
			if not silent then
				picker.AnimationChanged:Fire(mode)
			end
		end
		return picker
	end

	local function destroyPicker(picker)
		picker.Row:Destroy()
		picker._trove:Destroy()
	end

	local function setPickerValue(picker, value, silent)
		local rgb = value.Rgb
		if not rgb then
			rgb = picker.Color
		end
		local alpha = picker.Alpha
		if value.Alpha ~= nil then
			alpha = math.clamp(value.Alpha, 0, 1)
		end
		local stops = value.Stops
		local mode = picker.Mode
		if picker.Gradient == "off" then
			mode = "Solid"
			stops = nil
		elseif stops ~= nil then
			mode = 0 < #stops and "Gradient" or "Solid"
		end
		local val, sat, hue
		hue, sat, val = rgb:ToHSV()
		if mode == "Gradient" then
			local ensure = Stops.ensure
			if not stops then
				stops = picker.Stops
			end
			picker.Stops = ensure(stops, rgb)
			picker.ActiveStopIndex = math.clamp(picker.ActiveStopIndex, 1, #picker.Stops)
			local activeStop = getActiveStop(picker)
			if activeStop ~= nil then
				activeStop.Value = rgb
			end
		elseif not (stops == nil or not (0 < #stops)) then
			picker.Stops = Stops.ensure(stops, rgb)
		end
		if picker._dragMode == "sat" or picker._dragMode == "alpha" or not (0 < val and 0 < sat) then
			hue = picker.Hue
		end
		setPickerMode(picker, mode)
		picker.Hue = hue
		picker.Sat = sat
		picker.Val = val
		picker.Alpha = alpha
		picker:_applyState(silent)
	end

	local function enableAnimation(picker, allowBreathing)
		picker.Animatable = true
		picker._allowBreathing = allowBreathing
		local panel = picker._panel
		if panel ~= nil then
			panel.SetAnimationEnabled(true, allowBreathing)
		end
		return picker
	end

	local function getActiveStop_proto(picker)
		return picker.Stops[picker.ActiveStopIndex]
	end

	local function setPickerMode_proto(picker, mode)
		local isGradient
		isGradient = mode == "Gradient"
		if isGradient then
			isGradient = not (picker.Gradient == "off")
		end
		local newMode = "Solid"
		if isGradient then
			newMode = "Gradient"
		end
		picker.Mode = newMode
