		function MobileButtons:Register(flag, label, mode, onActivate)
			local existing = self._buttons[flag]
			if existing ~= nil then
				existing.trove:Destroy()
				self._buttons[flag] = nil
			end
			local button = {
				flag = flag,
				slot = self._buttonCount,
				mode = mode,
				active = false,
				visible = true,
				invisible = false,
				labelText = label,
				trove = self._trove:Extend(),
				onActivate = onActivate,
				rt = nil
			}
			self._buttons[flag] = button
			self._buttonCount = self._buttonCount + 1

			local function initialRefresh()
				if self._buttons[flag] == button then
					refreshVisibility(self, button)
				end
			end

			task.defer(initialRefresh)
			local handle = {}

			function handle:SetActive(active)
				button.active = active
				paintButton(self._menu, button)
			end

			function handle:SetMode(newMode)
				button.mode = newMode
				refreshVisibility(self, button)
			end

			function handle:SetLabel(newLabel)
				button.labelText = newLabel
				local rt = button.rt
				if rt ~= nil then
					rt.label.Text = newLabel
				end
			end

			function handle:SetVisible(visible)
				button.visible = visible
				refreshVisibility(self, button)
			end

			function handle:SetInvisible(invisible)
				button.invisible = invisible
				setTransparency(button, self._isDragMode)
			end

			function handle.Destroy()
				if self._buttons[flag] == button then
					self._buttons[flag] = nil
				end
				button.trove:Destroy()
			end

			return handle
		end

		function MobileButtons:EnterDragMode(onDone)
			self._isDragMode = true
			local menu = self._menu
			local textButton = Instance.new("TextButton")
			textButton.AnchorPoint = Vector2.new(0.5, 0)
			textButton.Position = UDim2.new(0.5, 0, 0, 40)
			textButton.Size = UDim2.fromOffset(140, 40)
			textButton.BackgroundColor3 = theme.get("Accent")
			textButton.BorderSizePixel = 0
			textButton.Text = "Done"
			textButton.FontFace = font
			textButton.TextSize = 16
			textButton.TextColor3 = Color3.fromRGB(255, 255, 255)
			textButton.AutoButtonColor = false
			textButton.Parent = self._parent
			local uiCorner = Instance.new("UICorner")
			uiCorner.CornerRadius = UDim.new(0, 6)
			uiCorner.Parent = textButton
			local dragTrove = self._trove:Extend()
			local allButtons = self._buttons
			local existingFlag = nil
			while true do
				local existingButton
				existingFlag, existingButton = allButtons(nil, existingFlag)
				if existingFlag == nil then
					break
				end
				setTransparency(existingButton, true)
				local existingRt = existingButton.rt
				if existingRt ~= nil then
					local tween = menu.Tween
					local existingStroke = existingRt.stroke
					local highlightGoal = { Thickness = 2 }
					tween(menu, existingStroke, highlightGoal)
				end
			end
			local buttons2 = self._buttons
			local flag2, draggingButton, dragInput, dragStart, startPosition
			while true do
				local button2
				flag2, button2 = buttons2(nil, flag2)
				if flag2 == nil then
					break
				end
				local buttonRt = button2.rt
				if buttonRt ~= nil then
					local capturedButton = button2
					local capturedRt = buttonRt

					local function onInputBegan(input)
						local inputType = input.UserInputType
						if not (inputType == Enum.UserInputType.Touch or
							inputType == Enum.UserInputType.MouseButton1) then
							return
						end
						draggingButton = capturedButton
						dragInput = input
						dragStart = input.Position
						startPosition = capturedRt.instance.Position
					end

					dragTrove:Connect(buttonRt.instance.InputBegan, onInputBegan)
				end
			end

			local function onInputChanged(input)
				local current = draggingButton
				local start = dragStart
				local startOffset = startPosition
				if current == nil or start == nil or startOffset == nil then
					return
				end
				local rt = current.rt
				if rt == nil then
					return
				end
				if not guiUtil.matchesPointerDrag(input, dragInput, Enum.UserInputType.MouseMovement) then
					return
				end
				local delta = input.Position - start
				rt.instance.Position = UDim2.fromOffset(
					startOffset.X.Offset + delta.X,
					startOffset.Y.Offset + delta.Y
				)
				guiUtil.clampGuiToViewport(rt.instance)
			end

			dragTrove:Connect(UserInputService.InputChanged, onInputChanged)

			local function onInputEnded(input)
				if draggingButton == nil then
					return
				end
				if not guiUtil.matchesPointerDrag(input, dragInput, Enum.UserInputType.MouseButton1) then
					return
				end
				draggingButton = nil
				dragInput = nil
				dragStart = nil
				startPosition = nil
			end

			dragTrove:Connect(UserInputService.InputEnded, onInputEnded)

			local function finishDragMode()
				self:_exitDragMode()
				local buttons = self._buttons
				local flag = nil
				while true do
					local button
					flag, button = buttons(nil, flag)
					if flag == nil then
						break
					end
					setTransparency(button, false)
					local rt = button.rt
					if rt ~= nil then
						local menuRef = menu
						local tween2 = menuRef.Tween
						local stroke = rt.stroke
						local goal = { Thickness = 1 }
						tween2(menuRef, stroke, goal)
					end
				end
				textButton:Destroy()
				dragTrove:Destroy()
				onDone()
			end

			dragTrove:Connect(textButton.Activated, finishDragMode)
		end

		function MobileButtons:_exitDragMode()
			self._isDragMode = false
			local state = self._menu:GetStateData()
			if state == nil then
				return
			end
			local positions = state.mobileButtonPositions
			if not positions then
				positions = {}
			end
			local buttons = self._buttons
			local flag = nil
			while true do
				local button
				flag, button = buttons(nil, flag)
				if flag == nil then
					break
				end
				if button.rt ~= nil then
					positions[flag] = table.create(2)
				end
			end
			state.mobileButtonPositions = positions
			self._menu:SaveState()
		end

		function MobileButtons:Destroy()
			self._trove:Destroy()
		end

		return MobileButtons
	end

