	local function applyAppearance(spoof, source)
		local head = spoof._character:FindFirstChild("Head")
		if not (head == nil or not head:IsA("BasePart")) then
			local originalHead = { transparency = head.Transparency }
			if head:IsA("MeshPart") then
				originalHead.meshId = head.MeshId
				originalHead.textureID = head.TextureID
			end
			spoof._originalHead = originalHead
		end
		for _, child in source:GetChildren() do
			if child:IsA("Accessory") then
				child.Parent = nil
				spoof._spoofedInstances[child] = true
				applyAccessory(child, spoof._character)
			elseif child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
				spoof._spoofedInstances[child] = true
				child.Parent = spoof._character
			elseif child:IsA("BasePart") then
				local targetPart = spoof._character:FindFirstChild(child.Name)
				if not (targetPart == nil or not targetPart:IsA("BasePart")) then
					targetPart.Color = child.Color
				end
			end
		end
		local sourceHead = source:FindFirstChild("Head")
		local targetHead = spoof._character:FindFirstChild("Head")
		if not (sourceHead == nil or targetHead == nil or not (sourceHead:IsA("BasePart") and targetHead:IsA("BasePart"))) then
			for _, decor in targetHead:GetChildren() do
				if isHeadDecor(decor) then
					spoof:_Stash(spoof._stashedHeadDecor, decor)
				end
			end
			for _, decor2 in sourceHead:GetChildren() do
				if isHeadDecor(decor2) then
					table.insert(spoof._spoofedHeadDecor, decor2)
					decor2.Parent = targetHead
				end
			end
			targetHead.Transparency = sourceHead.Transparency
			if sourceHead:IsA("MeshPart") and targetHead:IsA("MeshPart") then
				targetHead.MeshId = sourceHead.MeshId
				targetHead.TextureID = sourceHead.TextureID
			end
		end
	end

