	local function waitForParts(target, source, timeout)
		local promises = {}
		local seenParts = {}
		local seenAccessories = {}
		for _, child in source:GetChildren() do
			if child:IsA("Accessory") then
				local handle = child:FindFirstChild("Handle")
				if not (handle == nil or not handle:IsA("BasePart")) then
					local attachment = findAttachment(handle)
					if not (attachment == nil or seenAccessories[attachment.Name]) then
						seenAccessories[attachment.Name] = true
						table.insert(promises, waitForAttachment(target, attachment.Name, timeout))
					end
				end
			elseif child:IsA("BasePart") and not seenParts[child.Name] then
				seenParts[child.Name] = true
				table.insert(promises, waitForPartAsync(target, child.Name, timeout))
			end
		end
		return (Promise.all(promises))
	end

