				end
				decor:Destroy()
			end
			return
		end
		for _, child in character:GetChildren() do
			if spoof._spoofedInstances[child] then
				child:Destroy()
			end
		end
		local toRestore = spoof._stashed
		local stashedInstance = nil
		while true do
			local _
			stashedInstance, _ = toRestore(nil, stashedInstance)
			if stashedInstance == nil then
				break
			end
			if stashedInstance:IsA("Accessory") then
				applyAccessory(stashedInstance, character)
			else
				stashedInstance.Parent = character
			end
		end
		local originalHead = spoof._originalHead
		local head = character:FindFirstChild("Head")
		if not (head == nil or not head:IsA("BasePart") or originalHead == nil) then
			head.Transparency = originalHead.transparency
			if head:IsA("MeshPart") and originalHead.meshId ~= nil and
				originalHead.textureID ~= nil then
				head.MeshId = originalHead.meshId
				head.TextureID = originalHead.textureID
			end
		end
	end

