					self._spoofedInstances[child] = true
					child.Parent = self._character
				elseif child:IsA("BasePart") then
					local targetPart = self._character:FindFirstChild(child.Name)
					if not (targetPart == nil or not targetPart:IsA("BasePart")) then
						targetPart.Color = child.Color
