			end
			local sourceHead = source:FindFirstChild("Head")
			local targetHead = self._character:FindFirstChild("Head")
			if not (sourceHead == nil or targetHead == nil or
				not (sourceHead:IsA("BasePart") and targetHead:IsA("BasePart"))) then
