						decor2.Parent = targetHead
					end
				end
				targetHead.Transparency = sourceHead.Transparency
				if sourceHead:IsA("MeshPart") and targetHead:IsA("MeshPart") then
					targetHead.MeshId = sourceHead.MeshId
					targetHead.TextureID = sourceHead.TextureID
				end
			end
		end

		function CharacterSpoof:_Restore()
			local character = self._character
			if character.Parent == nil then
				local stashed = self._stashed
				local instance = nil
				while true do
					local _
					instance, _ = stashed(nil, instance)
					if instance == nil then
