				local count = #self._staticInstances
				table.move(self._staticInstances, 1, count, 1, combined)
				local entities = self._entityInstances
				local index = nil
				while true do
					local entity
					index, entity = entities(nil, index)
					if index == nil then
						break
					end
					local parts = self._entityPartsCache[entity]
					if parts ~= nil then
