	local function surfaceCFrame_proto(surface, depthUp, depthForward)
		return (CFrame.fromMatrix(
			surface.surfacePosition - surface.up * 0.01 - surface.up * depthUp + surface.forward * depthForward,
			surface.right,
			surface.up,
			-surface.forward
		))
	end

