			if not hazard then
				hazard = part:HasTag("KillBrick")
			end
			return hazard
		end

		local function nearHazard(position)
			local parts = workspace:GetPartBoundsInBox(CFrame.new(position), probeSize, overlapParams)
			local index = nil
			while true do
				local part
				index, part = parts(nil, index)
				if index == nil then
					break
				end
				if isHazard(part) then
					return true
				end
			end
			return false
		end

