			enemyPlayer, enemy = enemies(nil, enemyPlayer)
			if enemyPlayer == nil then
				break
			end
			if not (prioritizeHackers and self_._playerTags:Has(enemyPlayer, "Hacker") or not isValidTarget(enemy)) then
				return (toTarget(enemy))
			end
		end
		return nil
	end

