			self._selected = selected
		end

		function RouteMarker:Hide()
			local build = self._build
			if build.ready then
				build.billboard.Enabled = false
			end
		end

		function RouteMarker:Destroy()
			self._trove:Destroy()
		end

		return RouteMarker
