			local other = b[slot]
			if other == nil or other.Name ~= entry.Name then
				return false
			end
		end
		local slot2 = nil
		while true do
			local _
			slot2, _ = b(nil, slot2)
			if slot2 == nil then
				break
			end
			if a[slot2] == nil then
				return false
			end
		end
		return true
	end

