	local function renderGrid_proto(self_, parent, context)
-- [removed 1 line(s) containing unnamed identifiers]
		root.BackgroundTransparency = 1
		root.BorderSizePixel = 0
		root.Size = UDim2.new(1, 0, 0, self_._height)
		root.Parent = parent
		local scrollingFrame = Instance.new("ScrollingFrame")
		scrollingFrame.BackgroundTransparency = 1
		scrollingFrame.BorderSizePixel = 0
		scrollingFrame.Size = UDim2.fromScale(1, 1)
		local cellWidth = 0
		scrollingFrame.CanvasSize = UDim2.new(0, 0, 0, cellWidth)
		scrollingFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
		scrollingFrame.ScrollBarThickness = 0
		scrollingFrame.ScrollBarImageTransparency = 1
		scrollingFrame.Selectable = false
		cellWidth = "Accent"
		context.Batch:Bind(scrollingFrame, "ScrollBarImageColor3", cellWidth)
		scrollingFrame.Parent = root
		local uiGridLayout = Instance.new("UIGridLayout")
		uiGridLayout.CellSize = cardSize
		uiGridLayout.CellPadding = cardPadding
		uiGridLayout.SortOrder = Enum.SortOrder.LayoutOrder
		uiGridLayout.Parent = scrollingFrame
		cellWidth = -1
		local baseWidth = cardSize.X.Offset
		local gap = cardPadding.X.Offset
		local y = cardSize.Y

		local function updateGridCells()
			local x = scrollingFrame.AbsoluteSize.X
			if x < baseWidth then
				return
			end
			local columns = math.floor((x + gap) / (baseWidth + gap))
			if columns < 1 then
				columns = 1
			end
			local cellWidth2 = math.floor((x - gap * (columns - 1)) / columns)
			if cellWidth2 == cellWidth then
				return
			end
			cellWidth = cellWidth2
			uiGridLayout.CellSize = UDim2.new(0, cellWidth2, y.Scale, y.Offset)
		end

		context.Trove:Connect(scrollingFrame:GetPropertyChangedSignal("AbsoluteSize"), updateGridCells)
		task.defer(updateGridCells)
		self_._ctx = context
		local refs = { Holder = scrollingFrame }
		self_._rt = refs
		rebuildCards(self_)
		return root
	end

