	local function matchExtension_proto(url, extensions, fallback)
		local path = url:split("?")[1]:split("#")[1]:lower()
		local index = nil
		while true do
			local extension
			index, extension = extensions(nil, index)
			if index == nil then
				break
			end
			if path:sub(-#extension) == extension then
				return extension
			end
		end
		return fallback
	end

