					if c:IsKeyDown(Enum.KeyCode.S) then
						T = T - K
					end
					if c:IsKeyDown(Enum.KeyCode.D) then
						T = T + z.RightVector
					end
					if c:IsKeyDown(Enum.KeyCode.Space) then
						T = T + Vector3.new(0, 1, 0)
