					if c:IsKeyDown(Enum.KeyCode.LeftControl) or c:IsKeyDown(Enum.KeyCode.LeftShift) then
						T = T - Vector3.new(0, 1, 0)
					end
				else
					local c = U:GetControls():GetMoveVector()
					if c.Magnitude > 0 then
