	local function build_proto(section, weapon, profiles, weapons)
		local enabledPath = table.create(3)
		local addToggle = section.AddToggle
-- [removed 1 line(s) containing unnamed identifiers]
		local toggle = addToggle(section, toggleOptions)
		toggle:Set(profiles:Get(enabledPath), true)

		local function onToggleChanged(value)
			profiles:Set(enabledPath, value)
		end

		toggle:Connect(toggle.Changed, onToggleChanged)

		local function onConfigChanged(value)
			if toggle.Value ~= value then
				toggle:Set(value, true)
			end
		end

		toggle:Connect(profiles:GetPropertyChangedSignal(enabledPath), onConfigChanged)
		local profileOptions = concat(table.create(1), weapons.allWeapons)
		local addDropdown = section.AddDropdown
