	local function loadRandomEvasion()
		local RandomEvasion = {}
-- [removed 2 line(s) containing unnamed identifiers]
		local rng = Random.new()
		local farAway = 1073741824

		function RandomEvasion.compute(root)
			local settings = Config.data.Ragebot.Evasion.Random
			local baseRadius = settings.BaseRadius
			local extraRadius = baseRadius * settings.RadiusRandomFactor
			local position = root.Position
			local anchor = settings.AnchorFromCharacter
			anchor = anchor and position or Vector3.new(0, position.Y, 0)
			local offset = randomPointInShell(anchor, baseRadius, baseRadius + extraRadius)
			local axis = rng:NextInteger(1, 3)
			local offsetPosition = offset.Position
			local x = offsetPosition.X
			local y = offsetPosition.Y
			local z = offsetPosition.Z
			if axis == 1 then
				x = farAway
			elseif axis == 2 then
				y = farAway
			else
				z = farAway
			end
			return offset - offsetPosition + Vector3.new(x, y, z)
		end

		return RandomEvasion
	end

