	local function waitForChild_proto(parent, name, timeout)
		local function executor(resolve, reject)
			local child = parent:WaitForChild(name, timeout)
			if child then
				resolve(child)
			else
				string.format(
					"%s: timed out waiting for %s",
					tostring(parent:GetFullName()),
					tostring(name)
				)
				reject()
			end
		end

		return (Promise.new(executor))
	end

	local function loadWaitForCharacter()
-- [removed 1 line(s) containing unnamed identifiers]

		local function waitForChild(parent, name, timeout)
			local function executor(resolve, reject)
				local child = parent:WaitForChild(name, timeout)
				if child then
					resolve(child)
				else
					string.format(
						"%s: timed out waiting for %s",
						tostring(parent:GetFullName()),
						tostring(name)
					)
					reject()
				end
			end

			return (Promise.new(executor))
		end

		local requiredParts = table.create(15)

		local function waitForCharacter(character, timeout)
			local promises = table.create(1)
			waitForChild(character, "HumanoidRootPart", timeout)
			local parts = requiredParts
			local index = nil
			waitForChild(character, "Humanoid", timeout)
			while true do
				local partName
				index, partName = parts(nil, index)
				if index == nil then
					break
				end
				table.insert(promises, waitForChild(character, partName, timeout))
			end
			return (Promise.all(promises))
		end

		return waitForCharacter
	end

