			local payload, ok
-- [removed 1 line(s) containing unnamed identifiers]
			if not ok then
				local reporter = self._errorReporter
				local report = reporter.Report
				local err = Result.err
				string.format("failed to decode peer payload: %s", tostring(payload))
				report(reporter, err().error)
				return
			end
			if payload.shouldRemovePeer then
				self._items:ClearRemotePlayerOverrides(player)
