		local sendDelay = 0.5

		function CosmeticsBridge:NotifyStoresUpdated()
			local userServer = self._userServer
			if not (self._shareActive and userServer:IsShowActive() and userServer:IsConnected()) then
				return
			end
			if self._isSendQueued then
				return
			end
			self._isSendQueued = true

			local function flush()
				self._isSendQueued = false
				if self._shareActive and self._userServer:IsShowActive() and
					self._userServer:IsConnected() then
					self:_SendIfChanged()
				end
			end

			task.delay(sendDelay, flush)
		end

		function CosmeticsBridge:_TrySendCurrentInventory()
			local userServer = self._userServer
