	local function enforceWindow_proto(self_, track)
		local length = track.Length
		if length <= 0 then
			return
		end
		local settings = Config.data.AnimationPlayer
		local startTime = math.clamp(settings.Start, 0, 100) / 100 * length
		local endTime = math.clamp(settings.End, 0, 100) / 100 * length
		if endTime <= startTime then
			return
		end
		if endTime <= track.TimePosition or track.TimePosition < startTime then
			track.TimePosition = startTime
		end
	end

