	local function plan_proto(self_, deltaTime, target, shooter, ourPart, now)
		local head = target.aliveState.hitboxHead
		local isAbove
		isAbove = not (getVerticalSide(target.fighterState) == "Below")
		local ragebot = Config.data.Ragebot
		local offset
		if isAbove then
			offset = aboveOffset
		else
			offset = isAbove
		end
		if not offset then
			offset = belowOffset
		end
		local glued = self_._partGlue:Acquire(ourPart, head)
		self_._gluedOurPart = ourPart
		local cframe
		if isAbove then
			cframe = glued + offset
		else
			cframe = lookAt(glued.Position + offset, head.Position)
		end
		if not self_._shootLock:ShouldFire(now, deltaTime * ragebot.ShootFrames) then
			return 
				CFrame.new(
					math.random(-1000000, 1000000),
					math.random(5000, 10000),
					math.random(-1000000, 1000000)
				),
				nil
			
		end
		local origin
		if isAbove then
			origin = aboveOrigin
		else
			origin = isAbove
		end
		if not origin then
			origin = belowOrigin
		end
		isAbove = isAbove and aboveDirection or belowDirection
		local origin2 = origin
		local direction = isAbove

		local function shoot()
			shooter:ShootEncoded(origin2, direction, head, hitData)
		end

		return cframe, shoot
	end

