			local flatLook = Vector3.new(camera.LookVector.X, 0, camera.LookVector.Z)
			if flatLook.Magnitude < 0.0001 then
				return Vector3.zero
			end
			return (Vector3.new(
				direction:Dot(Vector3.new(camera.RightVector.X, 0, camera.RightVector.Z).Unit),
				0,
				-direction:Dot(flatLook.Unit)
			))
		end

		local function lerpRotation(from, to, alpha)
			return (Vector2.new(
				from.X + (to.X - from.X) * alpha,
				from.Y + ((to.Y - from.Y + math.pi) % (2 * math.pi) - math.pi) * alpha
			))
		end

		local alignEpsilon = math.rad(0.1)

		local function stepRotation(current, target, alpha, maxStep)
			local y = target.Y
			local y2 = current.Y
			local pi10 = math.pi
			local pi11 = math.pi
			local pi12 = math.pi
			local delta = Vector2.new(
				target.X - current.X,
				(y - y2 + pi10) % (2 * pi11) - pi12
			)
			local distance = delta.Magnitude
			if distance <= alignEpsilon then
				return target, true
			end
			return current + delta.Unit * math.min(distance * alpha, maxStep), false
		end

		local function smoothAlpha(deltaTime, timeConstant)
			return 1 - math.exp(-deltaTime / timeConstant)
		end

		local maxSmoothing = 0.3

		local function lookAlpha(deltaTime)
			return (smoothAlpha(deltaTime, Config.data.MovementRecorder.LookSmoothing / 100 * maxSmoothing))
		end

		local function findStartLook(anchor, keypoints)
			local index = nil
			while true do
				local keypoint
				index, keypoint = keypoints(nil, index)
				if index == nil then
					break
				end
				local action = keypoint.action
				if action.kind == "Look" then
					local yaw, pitch
					pitch, yaw = (anchor * action.cframe):ToOrientation()
					return (Vector2.new(pitch, yaw))
				end
			end
			return nil
		end

		local cameraPriority = 100

		function MovementReplay.new(aliveState, clientFighter, itemBehaviors, mapAnchor, recording, cameraDirector, isRoundActive, onFinished)
			cameraDirector:Claim(cameraClaimName, cameraPriority)
			local startEquippedIndex = recording.startEquippedIndex
			if startEquippedIndex ~= nil then
				task.spawn(safeCall, clientFighter.EquipItem, clientFighter, startEquippedIndex)
			end
			local replay = {
				_aliveState = aliveState,
				_clientFighter = clientFighter,
				_itemBehaviors = itemBehaviors,
				_startEquippedIndex = startEquippedIndex
			}
			local equipCooldown = recording.startEquipCooldown
			if not equipCooldown then
				equipCooldown = 0
			end
			replay._startEquipCooldown = equipCooldown
			replay._mapAnchor = mapAnchor
			replay._startCFrame = recording.startCFrame
			replay._keypoints = recording.keypoints
			replay._positions = recording.positions
			replay._positionIndex = 1
			replay._cameraDirector = cameraDirector
			replay._finishedCallback = onFinished
			replay._moveHook = MoveVectorHook.new()
			replay._isRoundActive = isRoundActive
			replay._startLookRotation = findStartLook(mapAnchor, recording.keypoints)
			replay._lookRotation = nil
			local alignState = { kind = "Aligning", elapsed = 0, stuckTime = 0, bestDistance = math.huge }
			replay._state = alignState
			replay._finished = false
			return (setmetatable(replay, MovementReplay))
		end

		local progressEpsilon = 0.1
		local stuckTimeout = 1
		local maxAlignTime = 3

		function MovementReplay:_StepAlign(state, deltaTime)
			local lookAligned = true
			local startLook = self._startLookRotation
			if startLook ~= nil then
				local rotation = CameraRotation.get()
				local alignSpeed = math.rad(Config.data.MovementRecorder.LookAlignSpeed)
				local nextRotation
				nextRotation, lookAligned = stepRotation(rotation, startLook, lookAlpha(deltaTime), alignSpeed * deltaTime)
				CameraRotation.set(nextRotation)
			end
			if not self._isRoundActive() then
				self._moveHook:SetMoveVector(Vector3.zero)
				return false
			end
			state.elapsed = state.elapsed + deltaTime
			local offset = (self._mapAnchor * self._startCFrame).Position - self._aliveState.rootPart.Position
			local flatOffset = Vector3.new(offset.X, 0, offset.Z)
			local distance = flatOffset.Magnitude
			local aligned
			aligned = distance <= Config.data.MovementRecorder.AlignSnapDistance
			if aligned then
				self._moveHook:SetMoveVector(Vector3.zero)
			else
				self._moveHook:SetMoveVector(worldToMoveVector(flatOffset.Unit))
			end
			if distance < state.bestDistance - progressEpsilon then
				state.bestDistance = distance
				state.stuckTime = 0
			else
				state.stuckTime = state.stuckTime + deltaTime
			end
			if aligned then
				aligned = lookAligned
			end
			if not aligned then
				aligned = stuckTimeout <= state.stuckTime
			end
			if not aligned then
				return false
			end
			self._moveHook:SetMoveVector(Vector3.zero)
			local ready = self:_IsStartItemReady()
			local timedOut
			timedOut = maxAlignTime <= state.elapsed
			if not ready then
				ready = timedOut
			end
			return ready
		end

		function MovementReplay:_IsStartItemReady()
			if self._startEquippedIndex == nil then
				return true
			end
			local equipped = self._itemBehaviors:GetEquipped()
			if equipped == nil or equipped.item.index ~= self._startEquippedIndex then
				return false
			end
			local cooldownEnd = getField(equipped.item.inner, "_equip_cooldown")
			local cooledDown
			cooledDown = not (type(cooldownEnd) == "number")
			if not cooledDown then
				cooledDown = cooldownEnd <= tick()
			end
			return cooledDown
		end

		function MovementReplay:Update(deltaTime)
			local state = self._state
			if state.kind == "Aligning" then
				if not self:_StepAlign(state, deltaTime) then
					return
				end
				local playState = { kind = "Playing", offset = 0, keypointIndex = 1 }
				self._state = playState
			end
			local state2 = self._state
			if state2.kind ~= "Playing" then
				return
			end
			state2.offset = state2.offset + deltaTime
			if self:_HasDiverged(state2.offset) then
				self._finished = true
				self._finishedCallback("Diverged")
				return
			end
			local keypoints = self._keypoints
			while state2.keypointIndex <= #keypoints do
				local keypoint = keypoints[state2.keypointIndex]
				if state2.offset < keypoint.offset then
					break
				end
				local action = keypoint.action
				if action.kind == "Move" then
					self._moveHook:SetMoveVector(action.direction)
				elseif action.kind == "Look" then
					local yaw, pitch
					pitch, yaw = (self._mapAnchor * action.cframe):ToOrientation()
					self._lookRotation = Vector2.new(pitch, yaw)
				elseif action.kind == "Equip" then
					task.spawn(
						safeCall,
						self._clientFighter.EquipItem,
						self._clientFighter,
						action.index
					)
				elseif action.kind == "ItemInput" then
					task.spawn(
						safeCall,
						self._clientFighter.Input,
						self._clientFighter,
						action.inputType
					)
				elseif action.kind == "QuickAttack" then
					task.spawn(
						safeCall,
						self._clientFighter.QuickAttack,
						self._clientFighter,
						action.attackType
					)
				elseif action.kind == "Jump" then
					if getField(MechanicsController, "IsSliding") == true then
						safeCall(MechanicsController.HighJump, MechanicsController)
					else
						safeCall(MechanicsController.DoubleJumpRequest, MechanicsController)
						safeCall(MechanicsController.JumpRequest, MechanicsController)
					end
				elseif action.kind == "Crouch" then
					safeCall(
						MechanicsController.SetCrouching,
						MechanicsController,
						action.crouching
					)
				elseif action.kind == "Slide" then
					task.spawn(safeCall, MechanicsController.Slide, MechanicsController)
				end
				state2.keypointIndex = state2.keypointIndex + 1
			end
			if self._lookRotation ~= nil then
				local setRotation = CameraRotation.set
				lerpRotation(CameraRotation.get(), self._lookRotation, lookAlpha(deltaTime))
				setRotation()
			end
			if not (self._finished or not (#keypoints < state2.keypointIndex)) then
				self._finished = true
				self._finishedCallback("Completed")
			end
		end

		local divergeDistance = 15

		function MovementReplay:_HasDiverged(offset)
			local positions = self._positions
			if #positions == 0 then
				return false
			end
			while self._positionIndex < #positions and
				positions[self._positionIndex + 1].offset <= offset do
				self._positionIndex = self._positionIndex + 1
			end
			local sample = positions[self._positionIndex]
			local nextSample = positions[self._positionIndex + 1]
			local alpha, expected
			if nextSample == nil then
				expected = sample.position
			else
				local span = nextSample.offset - sample.offset
				alpha = 0 < span
				alpha = alpha and math.clamp((offset - sample.offset) / span, 0, 1) or 0
				expected = sample.position:Lerp(nextSample.position, alpha)
			end
			local diverged
			diverged = divergeDistance < (self._mapAnchor:PointToWorldSpace(expected) - self._aliveState.rootPart.Position).Magnitude
			return diverged
		end

		function MovementReplay:Destroy()
			self._cameraDirector:Release(cameraClaimName)
			self._moveHook:Destroy()
			safeCall(MechanicsController.SetCrouching, MechanicsController, false)
		end

		return MovementReplay
	end

