		function ItemModifiers.new(itemBehaviors, cameraDirector, useItemHook)
			local trove = Trove.new("item_modifiers")
			local errorReporter = trove:Add(ErrorReporter.new())
			local modifiers = {
				_trove = trove,
				_errorReporter = errorReporter,
				_recoilModifier = trove:Add(RecoilModifier.new()),
				_motionDisabler = trove:Add(MotionDisabler.new(itemBehaviors)),
				_animationDisabler = trove:Add(AnimationDisabler.new()),
				_infoModifier = trove:Add(InfoModifier.new(itemBehaviors)),
				_equipCooldownModifier = trove:Add(EquipCooldownModifier.new(itemBehaviors)),
				_cameraShakeDisabler = trove:Add(CameraShakeDisabler.new()),
				_cameraSwayDisabler = trove:Add(CameraSwayDisabler.new(cameraDirector, errorReporter)),
				_noSpread = trove:Add(NoSpread.new(useItemHook:Reserve(), itemBehaviors)),
				_grenadeFuse = trove:Add(GrenadeFuse.new(useItemHook:Reserve(), itemBehaviors))
			}
			setmetatable(modifiers, ItemModifiers)
			modifiers:_SetupMotionDisabler(trove)
			modifiers:_SetupCameraShakeDisabler(trove, errorReporter)
			modifiers:_SetupCameraSwayDisabler(trove, errorReporter)
			modifiers:_SetupNoSpread(trove)
			modifiers:_SetupAimCooldown(trove)
			modifiers:_SetupAnimationDisabler(trove, errorReporter)
			modifiers:_SetupRecoilModifier(trove, errorReporter)
			modifiers:_SetupInfoModifier(trove)
			modifiers:_SetupGrenadeFuse(trove, errorReporter)
			return modifiers
		end

		function ItemModifiers:_SetupMotionDisabler(trove)
			local function sync()
				self._motionDisabler:SetMotionDisabled(Config.data.ItemModifiers.NoMotion)
			end

			trove:Connect(Config:GetPropertyChangedSignal((table.create(2))), sync)
			sync()
		end

