	local function updateColorAnimator_proto(self_, deltaTime)
		if next(self_._entries) == nil then
			return
		end
		local entries = self_._entries
		local key = nil
		while true do
			local entry
			key, entry = entries(nil, key)
			if key == nil then
				break
			end
			entry.t = entry.t + deltaTime * entry.speed
			if entry.mode == "Rainbow" then
				self_._callbacks.writeColor(entry.colorPath, ColorEffects.rainbow(entry.t))
			elseif entry.mode == "Breathing" and entry.transparencyPath ~= nil then
				self_._callbacks.writeTransparency(
					entry.transparencyPath,
					ColorEffects.breathing(entry.breathingMin, entry.breathingMax, entry.t)
				)
			end
		end
	end

