		function ColorAnimator.SetEntry(self_, colorPath, transparencyPath, options)
			local key = table.concat(colorPath, "/")
			local requestedMode = options.mode
			local mode
			mode = requestedMode == "Breathing"
			if mode then
				mode = transparencyPath == nil
			end
			mode = mode and "None" or requestedMode
			local existing = self_._entries[key]
			if mode == "None" then
				if existing ~= nil then
					self_._entries[key] = nil
					self_._callbacks.revertColor(colorPath)
					if transparencyPath ~= nil then
						self_._callbacks.revertTransparency(transparencyPath)
					end
				end
				return
			end
			if not (existing == nil or existing.mode ~= mode) then
				existing.speed = options.speed
				existing.transparencyPath = transparencyPath
				local breathingMin = options.breathingMin
				if not breathingMin then
					breathingMin = existing.breathingMin
				end
				existing.breathingMin = breathingMin
				local breathingMax = options.breathingMax
				if not breathingMax then
					breathingMax = existing.breathingMax
				end
				existing.breathingMax = breathingMax
				return
			end
			self_._callbacks.revertColor(colorPath)
			if transparencyPath ~= nil then
				self_._callbacks.revertTransparency(transparencyPath)
			end
			local entries = self_._entries
			local entry = { colorPath = colorPath, transparencyPath = transparencyPath, mode = mode, speed = options.speed }
			local phase
			phase = not (existing == nil)
			phase = phase and existing.t or 0
			entry.t = phase
			local minAlpha = options.breathingMin
			if not minAlpha then
				minAlpha = 0
			end
			entry.breathingMin = minAlpha
			local maxAlpha = options.breathingMax
			if not maxAlpha then
				maxAlpha = 1
			end
			entry.breathingMax = maxAlpha
			entries[key] = entry
		end

		function ColorAnimator:Update(deltaTime)
			if next(self._entries) == nil then
				return
			end
			local entries = self._entries
			local key = nil
			while true do
				local entry
				key, entry = entries(nil, key)
				if key == nil then
					break
				end
				entry.t = entry.t + deltaTime * entry.speed
				if entry.mode == "Rainbow" then
					self._callbacks.writeColor(entry.colorPath, ColorEffects.rainbow(entry.t))
				elseif entry.mode == "Breathing" and entry.transparencyPath ~= nil then
					self._callbacks.writeTransparency(
						entry.transparencyPath,
