		local offsetAngle = math.cos(math.rad(90))
		local pi = math.pi
		local pi2 = math.pi
		local _ = table.freeze
		local ArrowConstants = {
			X_INVERSE = xInverse,
			OFFSET_ANGLE = offsetAngle,
			ROLL_OFFSET_LOW = 0.2 * pi,
			ROLL_OFFSET_HIGH = 1.8 * pi2,
			FADE_EDGE = 0.1
		}
		return (table.freeze(ArrowConstants))
	end

