	local function applyLineImage_proto(frame, width, height, edgeMode, angle)
		if edgeMode == "Baked" then
			local imageHeight, imageWidth, image
			image, imageWidth, imageHeight = LineTextures.getRotated(width, height, angle)
			if image ~= nil then
				frame.Image = image
				frame.Size = UDim2.fromOffset(imageWidth, imageHeight)
				return true
			end
		elseif edgeMode == "Soft" then
			local pad = LineTextures.PAD * 2
			local image2 = LineTextures.get(width + pad, height + pad)
			if image2 ~= nil then
				frame.Image = image2
				frame.Size = UDim2.fromOffset(width + pad, height + pad)
				return true
			end
		end
		frame.Image = ""
		frame.Size = UDim2.fromOffset(width, height)
		return false
	end

	local function preloadAll_proto(list, onDone)
		if #list == 0 then
			return
		end

		local function preloadAndCleanup()
			ContentProvider:PreloadAsync(list)
			local instances = list
			local index = nil
			while true do
				local instance
				index, instance = instances(nil, index)
				if index == nil then
					break
				end
				instance:Destroy()
			end
			if onDone then
				onDone()
			end
		end

		task.spawn(preloadAndCleanup)
	end

	local function lineMetrics_proto(settings)
		local outlineThickness = settings.Outline.Enabled
		outlineThickness = outlineThickness and settings.Outline.Thickness or 0
		return settings.Thickness, settings.Length, outlineThickness
	end

	local function applyStatic_proto(self_, settings)
		self_._rotation = settings.Rotation
		local outline, length, thickness
		thickness, length, outline = lineMetrics(settings)
		local angle = settings.Rotation.Angle
		local signature = string.format(
			"%s:%s:%s:%s",
			tostring(thickness),
			tostring(length),
			tostring(outline),
			tostring(angle)
		)
		if signature ~= self_._bakeSignature then
			self_._bakeSignature = signature
			self_._bakeChangedAt = os.clock()
			table.clear(self_._warmed)

			local function preloadIfCurrent()
				if self_._bakeSignature == signature then
					self_:_PreloadTextures()
				end
			end

			task.delay(bakeDelay, preloadIfCurrent)
		end
		self_._edgeMode = self_:_ComputeEdgeMode(angle)
		self_._bakedAngle = angle
		self_:ApplyTextures()
	end

	local function preloadTextures_proto(self_)
		local settings = Config.data.CustomCrosshair
		lineMetrics(settings)
		local pad = LineTextures.PAD * 2
		local preloads = {}
		local sizes = table.create(2)
		table.create(2)
		table.create(2)
		local index = nil
		while true do
			local size
			index, size = sizes(nil, index)
			if index == nil then
				break
			end
			queuePreload(preloads, LineTextures.get(size[1] + pad, size[2] + pad))
			queuePreload(preloads, LineTextures.get(size[2] + pad, size[1] + pad))
		end
		preloadAll(preloads)
		if settings.Rotation.Angle % 90 ~= 0 then
			self_:_PreloadBakedAngle(settings.Rotation.Angle)
