					self_._lookupByType.Skin[itemName][name] = true
					self_._typeByName[name] = kind
					self_._inventory[name] = true
				elseif kind == "Wrap" then
					table.insert(self_._byType.Wrap, name)
					self_._lookupByType.Wrap[name] = true
					self_._typeByName[name] = kind
					self_._inventory[name] = allItemNames
				elseif kind == "Charm" then
					table.insert(self_._byType.Charm, name)
					self_._lookupByType.Charm[name] = true
					self_._typeByName[name] = kind
					self_._inventory[name] = allItemNames
				elseif kind == "Finisher" then
					table.insert(self_._byType.Finisher, name)
					self_._lookupByType.Finisher[name] = true
					self_._typeByName[name] = kind
					self_._inventory[name] = allItemNames
				elseif kind == "Emote" then
					self_._typeByName[name] = kind
					self_._inventory[name] = true
				end
			end
		end
