		function CosmeticCatalog.IsInCatalog(self_, query)
			if query.cosmeticName:match("^" .. NONE_COSMETIC) or
				query.cosmeticName == RANDOM_COSMETIC then
				return true
			end
			local found
			if query.cosmeticType ~= "Skin" then
				found = self_._lookupByType[query.cosmeticType][query.cosmeticName] == true
				return found
			end
			local skins = self_._lookupByType.Skin[query.itemName]
			local found2
			found2 = not (skins == nil)
			if found2 then
				found2 = skins[query.cosmeticName] == true
			end
			return found2
		end

		function CosmeticCatalog:IsCosmeticInCatalog(itemName, cosmeticName)
			if cosmeticName:match("^" .. NONE_COSMETIC) then
