			local itemTypes = CosmeticTypes.item
			local index = nil
			while true do
				local kind
				index, kind = itemTypes(nil, index)
				if index == nil then
					break
				end
				local isInCatalog = self.IsInCatalog
				local query = { cosmeticType = kind, itemName = itemName, cosmeticName = cosmeticName }
				if isInCatalog(self, query) then
					return true
				end
			end
			return false
		end

