				for wrapIndex2 = 1, 3 do
					local mid = bandCenter + wrapOffsets[wrapIndex2] - phase
					local low = mid - bandWidth
					local high = mid + bandWidth
					if 0 < high and low < 1 then
						if 0 < low then
							table.insert(stops, low)
						end
						if 0 <= mid and mid <= 1 then
							table.insert(stops, mid)
