	local function playResolvedEmote_proto(self_, entity, emote)
		safeCall(entity.CancelEmote, entity)
		if not safeCall(entity.IsAlive, entity) then
			return
		end
		local emoteModule = Emotes:FindFirstChild(emote.Name)
		if emoteModule == nil then
			return
		end
		local identity = getthreadidentity()
		setthreadidentity(2)
		local emoteInstance = require(emoteModule).new(entity.Humanoid)
		emoteInstance:SetSerial(emote)
		entity._current_emote = emoteInstance
		entity.EmoteStatusChanged:Fire()
		task.spawn(emoteInstance.PlayServer, emoteInstance)
		task.spawn(emoteInstance.PlayClient, emoteInstance)
		setthreadidentity(identity)
		self_.played:Fire(entity)
	end

