	local function encodeAuthRequest(msgType, key, userId, extra)
		local keyLen = #key
		local buf = buffer.create(2 + keyLen + 8 + 8)
		buffer.writeu8(buf, 0, msgType)
		buffer.writeu8(buf, 1, keyLen)
		buffer.writestring(buf, 2, key)
		local keyEnd = 2 + keyLen
		buffer.writeu32(buf, keyEnd, userId)
		local userIdEnd = keyEnd + 4
		buffer.writeu32(buf, userIdEnd, 0)
		local extraOffset = userIdEnd + 4
		buffer.writeu32(buf, extraOffset, extra)
		buffer.writeu32(buf, extraOffset + 4, 0)
		return (buffer.tostring(buf))
	end

