		return (buffer.tostring(buf))
	end

	local function decodeRecvEntries(data)
		if #data == 0 then
			return {}
		end
		local buf = buffer.fromstring(data)
		local bufLen = buffer.len(buf)
		local offset = 0
		local entries = {}
		while offset < bufLen do
			local userIdHash = buffer.readu32(buf, offset)
			local payloadOffset = offset + 8
			local payloadLen = buffer.readu32(buf, payloadOffset)
			local payloadStart = payloadOffset + 4
			local payloadBuf = buffer.create(payloadLen)
			buffer.copy(payloadBuf, 0, buf, payloadStart, payloadLen)
			offset = payloadStart + payloadLen
			local _ = table.insert
			local entry = { userIdHash = userIdHash, payload = buffer.tostring(payloadBuf) }
			table.insert(entries, entry)
		end
		return entries
	end

