			local saveResult = self._configManager:SaveToFile(fileName)
			if saveResult.success then
				return Result.VOID_OK
			end
			return (Result.err("Skyboxes", "Save", saveResult.message))
		end

		function Skyboxes:Add(name, faceIds)
			local trimmedName = trim(name)
			if trimmedName == "" then
				return (Result.err("Skyboxes", "Add", "skybox name cannot be empty"))
			end
			if self._presetByName[trimmedName] ~= nil then
				local err = Result.err
				string.format("a skybox named \"%s\" already exists", tostring(trimmedName))
				return (err())
			end
			local preset = {}
			local faceList = faces
			local index = nil
			while true do
				local face
				index, face = faceList(nil, index)
				if index == nil then
					break
				end
				local assetId = normalizeAssetId(faceIds[face])
				if assetId == nil then
					return (Result.err("Skyboxes", "Add", "all six skybox faces are required"))
				end
				preset[face] = assetId
			end
			self._data[trimmedName] = preset
			self:_RebuildIndexes()
			local saveResult = self:_Save()
			self.changed:Fire(self:GetNames())
			return saveResult
		end

		function Skyboxes:Remove(name)
			if self._data[name] == nil then
				return Result.VOID_OK
			end
			self._data[name] = nil
			self:_RebuildIndexes()
			local saveResult = self:_Save()
			self.changed:Fire(self:GetNames())
			return saveResult
		end

		function Skyboxes:Destroy()
			self._errorReporter:Destroy()
			self.changed:Destroy()
		end

		return Skyboxes
	end

