	local function spawnVisuals_proto(self_, mode, part, footParts, color, duration)
		local hasFeet
		hasFeet = 0 < #footParts
		if mode == "Circle" then
			if hasFeet then
				local index = nil
				while true do
					local foot
					index, foot = footParts(nil, index)
					if index == nil then
						break
					end
					local footSize = math.max(foot.Size.X, foot.Size.Z)
					self_:_SpawnCircle(groundCFrame(foot), color, duration, footSize * 0.5 + radiusPadding)
				end
			else
				local partSize = math.max(part.Size.X, part.Size.Z)
				self_:_SpawnCircle(groundCFrame(part), color, duration, partSize * 0.5 + radiusPadding)
			end
			return
		end
		local size
		if hasFeet then
			local index2 = nil
			while true do
				local foot2
				index2, foot2 = footParts(nil, index2)
				if index2 == nil then
					break
				end
				local footprintBox = Vector3.new(foot2.Size.X + footprintPadding, footprintHeight, foot2.Size.Z + footprintPadding)
				self_:_SpawnFootprint(groundCFrame(foot2), footprintBox, color, duration)
			end
		else
			size = 0 < part.Size.Magnitude
			size = size and part.Size or footprintSize
			self_:_SpawnFootprint(groundCFrame(part), size, color, duration)
		end
	end

