			if filter == "All" or model == nil then
				return true
			end
			local isSelf
			isSelf = model == LocalPlayer.Character
			if filter == "Self" then
				return isSelf
			end
			if isSelf then
				return false
			end
			local fighter = self._fighters.byModel[model]
			if fighter ~= nil then
				if filter == "Enemies" and not fighter.isEnemy then
					return false
				end
				if filter == "Team" and fighter.isEnemy then
					return false
				end
			end
			return true
		end

