	local function loadLookKinds()
-- [removed 1 line(s) containing unnamed identifiers]
		local LookKinds = {}
		local none = {
			kind = "None",
			speed = 0,
			shimmerColor = Color3.new(0.16, 0.16, 0.16),
			perimeterColor = ColorSequence.new(Color3.new(1, 1, 1)),
			pingPongBg = Color3.new(0, 0, 0),
			pingPongMain = Color3.new(1, 1, 1),
			pingPongRotation = 0
		}
		LookKinds.None = none

		function LookKinds.resolve(settings)
			local pingPong = settings.PingPong
			local kind = "None"
			local speed = 0
			if settings.Enabled then
				local requestedKind = settings.Kind
				if requestedKind == "Shimmer" then
					speed = settings.Shimmer.Speed
					kind = requestedKind
				elseif requestedKind == "Perimeter" then
					speed = settings.Perimeter.Speed
					kind = requestedKind
				elseif requestedKind == "PingPong" then
					speed = pingPong.Speed
					kind = requestedKind
				end
			end
			local look = {
				kind = kind,
				speed = speed,
				shimmerColor = settings.Shimmer.Color,
				perimeterColor = settings.Perimeter.Color,
				pingPongBg = pingPong.BackgroundColor,
				pingPongMain = pingPong.MainColor,
				pingPongRotation = pingPong.Rotation
			}
			return look
		end

		return LookKinds
	end

