								local TargetSwitchDelay = {}
								TargetSwitchDelay.__index = TargetSwitchDelay

								function TargetSwitchDelay.new()
									local fields = { _previousPlayer = nil, _pendingPlayer = nil, _pendingDuration = nil }
									return (setmetatable(fields, TargetSwitchDelay))
								end

								function TargetSwitchDelay:Reset()
									self._previousPlayer = nil
									self._pendingPlayer = nil
									self._pendingDuration = nil
								end

								function TargetSwitchDelay:Acquire(deltaTime, player, initialDelay, switchDelay)
									if self._previousPlayer == player then
										self._pendingPlayer = nil
										self._pendingDuration = nil
										return true
									end
									local delay
									delay = self._previousPlayer == nil
									delay = delay and initialDelay or switchDelay
									if delay <= 0 then
										self._previousPlayer = player
										self._pendingPlayer = nil
										self._pendingDuration = nil
										return true
									end
									if self._pendingPlayer ~= player then
										self._pendingPlayer = player
										self._pendingDuration = 0
										return false
									end
									local pending = self._pendingDuration
									if not pending then
										pending = 0
									end
									self._pendingDuration = pending + deltaTime
									if self._pendingDuration < delay then
										return false
									end
									self._previousPlayer = player
									self._pendingPlayer = nil
									self._pendingDuration = nil
									return true
								end

								return TargetSwitchDelay
							end

