									trove:Connect(self._enemyRegistry.added, onAdded)

									local function removeEntity(instance)
										local index = table.find(self._entityInstances, instance)
										if index ~= nil then
											swapRemove(self._entityInstances, index)
											self._entityPartsCache[instance] = nil
