								function Dropdown:SetOptions(options)
									if not options then
										options = {}
									end
									local current = self.Options
									if #options == #current then
										local same = true
										local index = nil
										while true do
											local option
											index, option = options(nil, index)
											if index == nil then
												break
											end
											if current[index] ~= option then
												same = false
												break
											end
										end
										if same then
											return
										end
									end
									self.Options = table.clone(options)
									rebuildIndex(self)
									rebuildRows(self)
									if not self.Multi then
										local value = self.Value
										if not (type(value) == "string" and
											self._indexByName[value] ~= nil) then
											self.Value = nil
										end
									end
									refreshRows(self, true)
									refreshValueLabel(self)
									self.ValueChanged:Fire(self.Value)
								end

								function Dropdown:Add(option)
									if not (type(option) == "string" and
										self._indexByName[option] == nil) then
										return
									end
									local options = table.clone(self.Options)
									table.insert(options, option)
									self:SetOptions(options)
								end

								function Dropdown:Remove(option)
									local index = self._indexByName[option]
									if index == nil then
										return
									end
									local options = table.clone(self.Options)
									table.remove(options, index)
									self:SetOptions(options)
								end

