								local function layout(self_)
									local rt = self_._rt
									if rt == nil then
										return
									end
									local inset = imageInset(self_)
									local hasSubtitle
									hasSubtitle = not (rt.Subtitle == nil)
									local hasImage
									hasImage = not (rt.Image == nil)
									if hasSubtitle then
										rt.Object.AutomaticSize = Enum.AutomaticSize.None
										rt.Object.Size = UDim2.new(1, 0, 0, 40)
										rt.Label.AnchorPoint = Vector2.new(0, 0)
										rt.Label.Position = UDim2.fromOffset(inset, 2)
										rt.Label.Size = UDim2.new(1, -inset, 0, 18)
										rt.Label.TextWrapped = false
										local subtitle = rt.Subtitle
										subtitle.Position = UDim2.fromOffset(inset, 22)
										subtitle.Size = UDim2.new(1, -inset, 0, 16)
									elseif hasImage then
										rt.Object.AutomaticSize = Enum.AutomaticSize.None
										rt.Object.Size = UDim2.new(1, 0, 0, 32)
										rt.Label.AnchorPoint = Vector2.new(0, 0.5)
										rt.Label.Position = UDim2.new(0, inset, 0.5, 0)
										rt.Label.Size = UDim2.new(1, -inset, 0, 0)
										rt.Label.TextWrapped = true
									else
										rt.Object.AutomaticSize = Enum.AutomaticSize.Y
										rt.Object.Size = UDim2.new(1, 0, 0, 24)
										rt.Label.AnchorPoint = Vector2.new(0, 0.5)
										rt.Label.Position = UDim2.fromScale(0, 0.5)
										rt.Label.Size = UDim2.fromScale(1, 0)
										rt.Label.TextWrapped = true
									end
								end

								local defaultImageSize = 28

								local function updateImage(row)
									local rt = row._rt
									if rt == nil then
										return
									end
									local image = row._image
									if image == nil or image == "" then
										if rt.Image ~= nil then
											rt.Image:Destroy()
											rt.Image = nil
											layout(row)
										end
										return
									end
									if rt.Image == nil then
										local size = row._imageSize
