									self._trove:Connect(self.Changed, callback)
									return self
								end

								function CardGrid:Connect(signal, callback)
									self._trove:Connect(signal, callback)
									return self
								end

								function CardGrid:Destroy()
									self.Row:Destroy()
									self._trove:Destroy()
								end

								return CardGrid
