								function KeybindCapture.new(trove)
									local fields = {
										_connection = nil,
										_active = nil,
										_captured = {}
									}
									local _ = setmetatable
									local captured = fields._captured
									local weakKeys = { __mode = "k" }
									setmetatable(captured, weakKeys)
									local capture = setmetatable(fields, KeybindCapture)

									local function cancelOnDestroy()
										capture:Cancel()
									end

									trove:Add(cancelOnDestroy)
									return capture
								end

								function KeybindCapture:ShouldBlockMenuToggle(input)
									local blocked
									blocked = not (self._active == nil)
									if not blocked then
										blocked = self._captured[input] == true
									end
									return blocked
								end

								function KeybindCapture:Begin(callback)
									self:Cancel()
									self._active = callback

									local function onInputBegan(input, gameProcessed)
										local inputType = input.UserInputType
										local isKeyboard
										isKeyboard = inputType == Enum.UserInputType.Keyboard
										local isMouse
										isMouse = inputType == Enum.UserInputType.MouseButton1
										if not isMouse then
											isMouse = inputType == Enum.UserInputType.MouseButton2
										end
										if not isMouse then
											isMouse = inputType == Enum.UserInputType.MouseButton3
										end
										if not (isKeyboard or isMouse) then
											return
										end
										local isClear
										if isKeyboard then
											isClear = input.KeyCode == Enum.KeyCode.Escape
											if not isClear then
												isClear = input.KeyCode == Enum.KeyCode.Unknown
											end
										else
											isClear = isKeyboard
										end
										if isKeyboard and not isClear and gameProcessed then
											return
										end
										local callback2 = self._active
										self:_disarm()
										if callback2 == nil then
											return
										end
										local result = "None"
										if not isClear then
											if isKeyboard then
												result = input.KeyCode
											else
												result = inputType
											end
										end
										self._captured[input] = true

										local function deliver()
											self._captured[input] = nil
											callback2(result)
										end

										task.defer(deliver)
									end

									self._connection = UserInputService.InputBegan:Connect(onInputBegan)

									local function cancel()
										if self._active == callback then
											self:Cancel()
										end
									end

									return cancel
								end

								function KeybindCapture:_disarm()
									local connection = self._connection
									if connection ~= nil then
										connection:Disconnect()
										self._connection = nil
									end
									self._active = nil
								end

								function KeybindCapture:Cancel()
									local callback3 = self._active
									self:_disarm()
									if callback3 ~= nil then
										callback3(nil)
									end
								end

								return KeybindCapture
							end

