										local elapsed = os.clock() - startTime
										if 0 < elapsed then
											local frames = self_._frames
											self_._smooth = self_._smooth + (frames / elapsed - self_._smooth) * smoothing
										end
										self_._frames = 0
										local fps = math.floor(self_._smooth + 0.5)
										if fps ~= self_._displayed then
											self_._displayed = fps
											self_._onDisplay(fps)
										end
										scheduleTick(self_)
									end

									task.delay(interval, sample)
								end

