								local function fadeTransparency(self_, instance, visible)
									local original = originalTransparency[instance]
									if original == nil then
										original = instance.Transparency
										originalTransparency[instance] = original
									end
									local tweener = self_._tweener
									local play = tweener.Play
									local goal = {}
									local target
									if visible then
										target = original
									else
										target = visible
									end
									if not target then
										target = 1
									end
									goal.Transparency = target
									local tween = play(tweener, instance, goal)
									if tween == nil then
										instance.Transparency = original
										return nil
									end
									local start
									start = visible and 1 or visible
									local final = original
									if not start then
										final = original
										start = original
									end
									instance.Transparency = start

									local function onCompleted()
										if instance.Parent == nil then
											return
										end
										if not visible then
											instance.Transparency = final
										end
									end

									tween.Completed:Once(onCompleted)
									return tween
								end

								function Menu.FadeGroupStrokes(self_, group, visible)
									for _, child in group:GetChildren() do
										if child:IsA("UIStroke") then
											fadeTransparency(self_, child, visible)
										end
									end
								end

								function Menu:FadeCanvasGroup(group, visible, state)
									if not state then
										state = { tweening = false }
									end
									local token = state._fadeToken
									if not token then
										token = 0
									end
									state._fadeToken = token + 1
									local token2 = state._fadeToken
									for _, child in group:GetChildren() do
										if child:IsA("UIStroke") then
											fadeTransparency(self, child, visible)
										end
									end
									if visible then
										group.Visible = true
									end
									local transparency = 1
									if visible then
										transparency = 0
									end
									local tweener = self._tweener
									local play = tweener.Play
									local goal = { GroupTransparency = transparency }
									local tween = play(tweener, group, goal)
									if tween == nil then
										group.GroupTransparency = transparency
										group.Visible = visible
										state.tweening = false
										return
									end
									state.tweening = true
									local fadeState = state

									local function onCompleted()
										if fadeState._fadeToken ~= token2 then
											return
										end
										fadeState.tweening = false
										group.Visible = visible
									end

									tween.Completed:Once(onCompleted)
								end

