										if startPosition == nil then
											return
										end
										local drag = detector.DragUDim2
										gui.Position = UDim2.new(
											startPosition.X.Scale,
											startPosition.X.Offset + drag.X.Offset,
											startPosition.Y.Scale,
											startPosition.Y.Offset + drag.Y.Offset
