										local kind = getField(cosmetic, "Type")
										if self._typeSet[kind] and
											self._raritySet[getField(cosmetic, "Rarity")] then
											if kind == "Skin" then
												local itemName = getField(cosmetic, "ItemName")
												if self._byType.Skin[itemName] == nil then
