												end
												table.insert(self._byType.Skin[itemName], name)
												self._lookupByType.Skin[itemName][name] = true
												self._typeByName[name] = kind
												self._inventory[name] = true
											elseif kind == "Wrap" then
												table.insert(self._byType.Wrap, name)
												self._lookupByType.Wrap[name] = true
												self._typeByName[name] = kind
