												self._lookupByType.Charm[name] = true
												self._typeByName[name] = kind
												self._inventory[name] = allItemNames
											elseif kind == "Finisher" then
												table.insert(self._byType.Finisher, name)
												self._lookupByType.Finisher[name] = true
												self._typeByName[name] = kind
												self._inventory[name] = allItemNames
											elseif kind == "Emote" then
