								function CosmeticCatalog.GetRandomCosmetic(self_, query)
									local candidates
									if query.cosmeticType == "Skin" then
										candidates = self_._byType.Skin[query.itemName]
									else
										candidates = self_._byType[query.cosmeticType]
									end
									if candidates == nil or #candidates == 0 then
										return nil
									end
									local count = #candidates + 1
									local pick = math.random(count)
									local result
									result = pick == count
									result = result and NONE_COSMETIC or candidates[pick]
									return result
								end

