									local types = CosmeticTypes.item
									local index = nil
									while true do
										local cosmeticType
										index, cosmeticType = types(nil, index)
										if index == nil then
											break
										end
										local isInCatalog = self.IsInCatalog
										local query = { cosmeticType = cosmeticType, itemName = itemName, cosmeticName = cosmeticName }
										if isInCatalog(self, query) then
											return true
										end
									end
									return false
								end

								function CosmeticCatalog:IsCosmeticType(name, kind)
									local matches
									matches = self._typeByName[name] == kind
									return matches
								end

