								local SelectionResolver = {}
								SelectionResolver.__index = SelectionResolver

								local function pruneMissing(map, valid)
									local key = nil
									while true do
										local _
										key, _ = map(nil, key)
										if key == nil then
											break
										end
										if valid[key] == nil then
											map[key] = nil
										end
									end
