								function SelectionResolver.new(intent, catalog, favoritedResolver, onlyUseFavoritesState)
									local fields = {
										_intent = intent,
										_catalog = catalog,
										_favoritedResolver = favoritedResolver,
										_onlyUseFavoritesState = onlyUseFavoritesState,
										_resolved = {},
