									local item = CosmeticsPage.getSelectedItem()
									local cosmeticType = CosmeticsPage.getCustomizingType()
									if item == nil or cosmeticType == nil or
										not CosmeticTypes.isItemCosmeticType(cosmeticType) then
										return nil, nil
