								local function rainbowSequence(saturation, offset, time)
									local keypoints = {}
									local steps = keypointCount
									for step = 0, steps do
										local position = step / keypointCount
										local color = sampleColorSequence(saturation, ((offset + position) / 4 - time) % 1)
