								local function getEspTextSettings()
									local settings = Config.data.ESP.Settings
									local textSettings = {
										textCase = settings.TextCase,
										flagTextCase = settings.FlagTextCase,
										textSurround = settings.TextSurround,
										flagTextSurround = settings.FlagTextSurround,
										font = Fonts:Get(settings.Font),
										flagFont = Fonts:Get(settings.FlagFont),
										fontSize = settings.FontSize,
										flagFontSize = settings.FlagFontSize,
										distanceScaling = settings.DistanceScaling,
										distanceScalingRef = settings.DistanceScalingRef
									}
									return textSettings
								end

								local function reconcileCalculator(entry)
									local main = Config.data.ESP.Main
									local calculator = entry.dynamicRectCalculator
									if main.Enabled and main.Mode ~= "Static" then
										if main.Mode == "Dynamic" then
											if calculator ~= nil then
												return
											end
											local aliveState = entry.aliveState
											if aliveState == nil then
												return
											end
											entry.dynamicRectCalculator = entry.trove:Add(DynamicRectCalculator.new(aliveState.model))
										end
									else
										if calculator == nil then
											return
										end
										entry.trove:Remove(calculator)
										entry.dynamicRectCalculator = nil
									end
								end

