								function Controller.new(fighters, playerIdentities)
									local trove = Trove.new("esp.controller")
									local formatting = getEspTextSettings()
									local self_ = {
										_trove = trove,
										_playerIdentities = playerIdentities,
										_entries = {},
										_hidden = true,
										_mainEnabled = false,
										_enemyEnabled = false,
										_teamEnabled = false,
										_formatting = formatting,
										_useDisplayName = Config.data.ESP.Settings.UseDisplayName,
										_mainMode = Config.data.ESP.Main.Mode,
										_overrideRectSize = Config.data.ESP.Settings.OverrideRectSize,
										_spacing = Config.data.ESP.Settings.Spacing,
										_boundCamera = workspace.CurrentCamera
									}
									local snapshot = {
										enabled = false,
										fighterState = nil,
										aliveState = nil,
										playerSettings = nil,
										formatting = formatting,
										displayedName = ""
									}
									self_._sharedSnapshot = snapshot
									local paneContext = {
										deltaTime = 0,
										clock = 0,
										fighterState = nil,
										aliveState = nil,
										distance = 0,
										playerSettings = nil,
										formatting = formatting
									}
									self_._sharedPaneContext = paneContext
									local independentContext = { cullHeavyOperations = true, halfFovTan = 0, viewportHeight = 0 }
									self_._sharedIndependentContext = independentContext
									setmetatable(self_, Controller)

									local function onSettingsChanged()
										local newFormatting = getEspTextSettings()
										self_._formatting = newFormatting
										self_._sharedSnapshot.formatting = newFormatting
										self_._sharedPaneContext.formatting = newFormatting
										self_._useDisplayName = Config.data.ESP.Settings.UseDisplayName
										self_._overrideRectSize = Config.data.ESP.Settings.OverrideRectSize
										self_._spacing = Config.data.ESP.Settings.Spacing
										local entries = self_._entries
										local key = nil
										while true do
											local entry
											key, entry = entries(nil, key)
											if key == nil then
												break
											end
											entry.esp:SetSpacing(self_._spacing)
										end
										self_:_MarkAllDirty()
									end

									trove:Connect(
										Config:GetPropertyChangedSignal((table.create(2))),
										onSettingsChanged
									)

									local function onModeChanged()
										self_._mainMode = Config.data.ESP.Main.Mode
										self_:_MarkAllDirty()
										self_:_ReconcileCalculators()
									end

									trove:Connect(
										Config:GetPropertyChangedSignal((table.create(2))),
										onModeChanged
									)

									local function onFontChanged()
										syncPingPongFlipbooks()
										self_:_MarkAllDirty()
									end

									trove:Connect(
										Config:GetPropertyChangedSignal((table.create(2))),
										onFontChanged
									)

									local function onFlagFontChanged()
										syncPingPongFlipbooks()
										self_:_MarkAllDirty()
									end

									trove:Connect(
										Config:GetPropertyChangedSignal((table.create(2))),
										onFlagFontChanged
									)

									local function onMainKeybind(enabled)
										self_._mainEnabled = enabled
										self_:_MarkAllDirty()
									end

									trove:Add(Keybinds:ObserveEnabledKeybind(table.create(2), onMainKeybind))

									local function onEnemyKeybind(enabled)
										self_._enemyEnabled = enabled
										self_:_MarkAllDirty()
									end

									trove:Add(Keybinds:ObserveEnabledKeybind(table.create(2), onEnemyKeybind))

									local function onTeamKeybind(enabled)
										self_._teamEnabled = enabled
										self_:_MarkAllDirty()
									end

									trove:Add(Keybinds:ObserveEnabledKeybind(table.create(2), onTeamKeybind))

									local function bindCamera()
										self_._boundCamera = workspace.CurrentCamera
