									trove:Connect(playerIdentities.identityRegistered, onIdentityChanged)
									trove:Connect(playerIdentities.identityChanged, onIdentityChanged)

									local function onAdded(state)
										self_:_AddRemoteState(state)
									end

									local function onRemoved(state)
										self_:_RemoveRemoteState(state)
									end

									fighters:ObserveRemoteStates(self_._trove, onAdded, onRemoved)
									syncPingPongFlipbooks()
									return self_
								end

								function Controller:_MarkPlayerDirty(player)
									local entries = self._entries
									local index = nil
									while true do
										local entry
										index, entry = entries(nil, index)
										if index == nil then
											break
										end
										if entry.fighterState.player == player then
											entry.dirty = true
											return
										end
									end
								end

								function Controller:_MarkAllDirty()
									local entries = self._entries
									local index = nil
									while true do
										local entry
										index, entry = entries(nil, index)
										if index == nil then
											break
										end
										entry.dirty = true
									end
								end

								function Controller:_AddRemoteState(fighterState)
									local entryTrove = self._trove:Extend()
									local esp = entryTrove:Add(PlayerEsp.new(layout))
									esp:SetSpacing(self._spacing)
									local entry = {
										esp = esp,
										trove = entryTrove,
										dynamicRectCalculator = nil,
										aliveState = nil,
										fighterState = fighterState,
										playerSettings = Config.data.ESP.Team,
										dirty = true,
										allInactive = false
									}

									local function onCharacterCreated(aliveState)
										local calculator = entry.dynamicRectCalculator
										if calculator ~= nil then
											entryTrove:Remove(calculator)
											entry.dynamicRectCalculator = nil
										end
										entry.aliveState = aliveState
										entry.dirty = true
										reconcileCalculator(entry)
									end

									local function onCharacterDied()
										local calculator2 = entry.dynamicRectCalculator
										if calculator2 ~= nil then
											entryTrove:Remove(calculator2)
											entry.dynamicRectCalculator = nil
										end
										entry.aliveState = nil
										entry.dirty = true
									end

									local function markDirty()
										entry.dirty = true
									end

									local character = fighterState.character
									entryTrove:Connect(character.created, onCharacterCreated)
									entryTrove:Connect(character.died, onCharacterDied)
									local state = character.state
									if state.alive then
										onCharacterCreated(state)
									end
									entryTrove:Connect(fighterState.enemyChanged, markDirty)
									entryTrove:Connect(fighterState.environmentIDChanged, markDirty)
									entryTrove:Connect(fighterState.itemObserver.itemChanged, markDirty)
									entryTrove:Connect(
										fighterState.player:GetAttributeChangedSignal("StatisticDuelsWinStreak"),
										markDirty
									)
									entryTrove:Connect(
										fighterState.player:GetAttributeChangedSignal("DisplayELO"),
										markDirty
									)
