								local Result = modules.b()
								local Signal = modules.t()
								modules.fw()
								local saveFolder = "kiciahook/rivals_v3"
								local fileName = "skyboxes.json"
								local filePath = string.format("%s/%s", tostring(saveFolder), tostring(fileName))
								local fieldTypes = {
									SkyboxBk = "string",
									SkyboxDn = "string",
									SkyboxFt = "string",
									SkyboxLf = "string",
									SkyboxRt = "string",
									SkyboxUp = "string",
									StarCount = "number",
									CelestialBodiesShown = "boolean",
									SunAngularSize = "number",
									MoonAngularSize = "number",
									SunTextureId = "string",
									MoonTextureId = "string"
								}
								local faces = table.create(6)

								local function trim(text)
									local trimmed = text:match("^%s*(.-)%s*$")
									if not trimmed then
										trimmed = ""
									end
									return trimmed
								end

								local function toAssetId(value)
									if type(value) == "number" then
										return (string.format("rbxassetid://%s", tostring(value)))
									end
									if type(value) ~= "string" then
										return nil
									end
									local trimmed = trim(value)
									if trimmed == "" then
										return nil
									end
									local digits = trimmed:match("^(%d+)$")
									if digits == nil then
										return trimmed
									end
									return (string.format("rbxassetid://%s", tostring(digits)))
								end

								local function filterTypedFields(data)
									local result = {}
									local key = nil
									while true do
										local value
										key, value = data(nil, key)
										if key == nil then
											break
										end
										if type(value) == fieldTypes[key] then
											result[key] = value
										end
									end
									return result
								end

								local function copyTableMap(value)
									local result = {}
									local source
-- [removed 1 line(s) containing unnamed identifiers]
									source = source and value or nil
									if source ~= nil then
										local key = nil
										while true do
											local entry
											key, entry = source(nil, key)
											if key == nil then
												break
											end
-- [removed 1 line(s) containing unnamed identifiers]
												not (key == "" or result[key] ~= nil) then
												result[key] = filterTypedFields(entry)
											end
										end
									end
									return result
								end

								local Skyboxes = {}
								Skyboxes.__index = Skyboxes

								function Skyboxes.new()
									local skyboxes = { _errorReporter = ErrorReporter.new() }
									local new = ConfigManager.new
									local managerOptions = {
										defaultConfig = defaultSkyboxes,
										currentVersion = 1,
										savePath = saveFolder,
										deserialize = copyTableMap
									}
									skyboxes._configManager = new(managerOptions)
									skyboxes._data = table.clone(defaultSkyboxes)
									skyboxes._names = {}
									skyboxes._presetByName = {}
									skyboxes.changed = Signal.new()
									setmetatable(skyboxes, Skyboxes)
									return skyboxes
								end

								function Skyboxes:Initialize()
									self._errorReporter:ReportResult(self:_EnsureDefaultFile())
									self._errorReporter:ReportResult(self:Reload())
								end

								function Skyboxes:_EnsureDefaultFile()
									if isfile(filePath) then
										return Result.VOID_OK
									end
									local saveResult = self._configManager:SaveDefaultToFile(fileName, true)
									if saveResult.success then
										return Result.VOID_OK
									end
									local makeError = Result.err
									string.format(
										"Failed to create default skybox config: %s",
										tostring(saveResult.message)
									)
									return (makeError())
								end

								function Skyboxes:Reload()
									self:_EnsureDefaultFile()
									local loadResult = self._configManager:LoadFromFile(fileName)
									if loadResult.success then
										self._data = loadResult.data
										self:_RebuildIndexes()
										self.changed:Fire(self:GetNames())
										return Result.VOID_OK
									end
									self._data = table.clone(defaultSkyboxes)
									self:_RebuildIndexes()
									self.changed:Fire(self:GetNames())
									return (Result.err("Skyboxes", "Reload", loadResult.message))
								end

								function Skyboxes:_RebuildIndexes()
									local names = {}
									local presetByName = {}
									local data = self._data
									local name = nil
									while true do
										local preset
										name, preset = data(nil, name)
										if name == nil then
											break
										end
										table.insert(names, name)
										presetByName[name] = preset
									end
									table.sort(names)
									self._names = names
									self._presetByName = presetByName
								end

								function Skyboxes:GetNames()
									return (table.clone(self._names))
								end

								function Skyboxes:GetPreset(name)
									local preset
									preset = not (name == nil)
									preset = preset and self._presetByName[name] or nil
									return preset
								end

								function Skyboxes:_Save()
									self._configManager:SetData(self._data)
									local saveResult = self._configManager:SaveToFile(fileName)
									if saveResult.success then
										return Result.VOID_OK
									end
									return (Result.err("Skyboxes", "Save", saveResult.message))
								end

								function Skyboxes:Add(name, faces2)
									local trimmedName = trim(name)
									if trimmedName == "" then
										return (Result.err("Skyboxes", "Add", "skybox name cannot be empty"))
									end
									if self._presetByName[trimmedName] ~= nil then
										local makeError = Result.err
										string.format(
											"a skybox named \"%s\" already exists",
											tostring(trimmedName)
										)
										return (makeError())
									end
									local skybox = {}
									local faceNames = faces
									local index = nil
									while true do
										local faceName
										index, faceName = faceNames(nil, index)
										if index == nil then
											break
										end
										local assetId = toAssetId(faces2[faceName])
										if assetId == nil then
											return (Result.err(
												"Skyboxes",
												"Add",
												"all six skybox faces are required"
											))
										end
										skybox[faceName] = assetId
									end
									self._data[trimmedName] = skybox
									self:_RebuildIndexes()
									local saved = self:_Save()
									self.changed:Fire(self:GetNames())
									return saved
								end

								function Skyboxes:Remove(name)
									if self._data[name] == nil then
										return Result.VOID_OK
									end
									self._data[name] = nil
									self:_RebuildIndexes()
									local saveResult = self:_Save()
									self.changed:Fire(self:GetNames())
									return saveResult
								end

								function Skyboxes:Destroy()
									self._errorReporter:Destroy()
									self.changed:Destroy()
								end

								return Skyboxes
							end

