								local Config = modules.y()
								modules.p()
								modules.aT()
								local Trove = modules.q()
								local Players = cloneref(game:GetService("Players"))
								local Workspace = cloneref(game:GetService("Workspace"))
								local LocalPlayer = Players.LocalPlayer
								local footPartNames = table.create(2)
								local rootPartNames = table.create(2)
								local footprintSize = Vector3.new(2, 0.2, 2)
								local SoundEsp = {}
								SoundEsp.__index = SoundEsp

								local function getSoundPart(sound)
									local parent = sound.Parent
									if parent == nil then
										return nil
									end
									if parent:IsA("BasePart") then
										return parent
									end
									if parent:IsA("Attachment") then
										local grandparent = parent.Parent
										if not (grandparent == nil or not grandparent:IsA("BasePart")) then
											return grandparent
										end
									end
									return nil
								end

								local function getFootParts(character)
									local parts = {}
									local names = footPartNames
									local index = nil
									while true do
										local name
										index, name = names(nil, index)
										if index == nil then
											break
										end
										local part = character:FindFirstChild(name)
										if not (part == nil or
											not part:IsA("BasePart")) then
											table.insert(parts, part)
										end
									end
									if 0 < #parts then
										return parts
									end
									local names2 = rootPartNames
									local index2 = nil
									while true do
										local name2
										index2, name2 = names2(nil, index2)
										if index2 == nil then
											break
										end
										local part2 = character:FindFirstChild(name2)
										if not (part2 == nil or
											not part2:IsA("BasePart")) then
											table.insert(parts, part2)
										end
									end
									return parts
								end

								local function loudnessColor(loudness)
									if loudness <= 0.5 then
										return (Color3.new(loudness * 2, 1, 0))
									end
									return (Color3.new(1, (1 - loudness) * 2, 0))
								end

								local function groundCFrame(part)
									local yaw, _
									_, yaw = part.CFrame:ToEulerAnglesYXZ()
									return CFrame.new(part.Position - Vector3.new(0, part.Size.Y * 0.5, 0)) * CFrame.Angles(0, yaw, 0)
								end

								local function easeOutQuint(t)
									return 1 - (1 - t) ^ 5
								end

								function SoundEsp.new(fighters)
									local trove = Trove.new()
									local folder = Instance.new("Folder")
									folder.Name = "RivalsSoundVisualizer"
									folder.Parent = Workspace
									trove:Add(folder)
									local visualizer = {
										_trove = trove,
										_fighters = fighters,
										_adornFolder = folder,
										_descendantAddedConnection = nil,
										_hooksBySound = {},
										_lastPlayedAt = {},
										_activeEffects = {},
										_circlePool = {},
										_footprintPool = {}
									}
									setmetatable(visualizer, SoundEsp)
									visualizer:_Initialize()
									return visualizer
								end

								function SoundEsp:_Initialize()
									local function onEnabledChanged(enabled)
										self:_SetEnabled(enabled)
									end

									self._trove:Connect(
										Config:GetPropertyChangedSignal((table.create(2))),
										onEnabledChanged
									)
									self:_SetEnabled(Config.data.SoundVisualizer.Enabled)
								end

								function SoundEsp:_SetEnabled(enabled)
									local tracking
									tracking = not (self._descendantAddedConnection == nil)
									if enabled == tracking then
										return
									end
									if enabled then
										self:_StartTracking()
									else
										self:_StopTracking()
									end
								end

								function SoundEsp:_StartTracking()
									local function onDescendantAdded(descendant)
										if descendant:IsA("Sound") then
											self:_TrackSound(descendant)
										end
									end

									self._descendantAddedConnection = Workspace.DescendantAdded:Connect(onDescendantAdded)
									for _, sound in Workspace:QueryDescendants("Sound") do
										self:_TrackSound(sound)
									end
								end

								function SoundEsp:_StopTracking()
									local connection = self._descendantAddedConnection
									if connection == nil then
										return
									end
									self._descendantAddedConnection = nil
									connection:Disconnect()
									local hooks = self._hooksBySound
									local sound = nil
									while true do
										local hook
										sound, hook = hooks(nil, sound)
										if sound == nil then
											break
										end
										hook.played:Disconnect()
										hook.destroying:Disconnect()
									end
									table.clear(self._hooksBySound)
									table.clear(self._lastPlayedAt)
								end

								function SoundEsp:_TrackSound(sound)
									if self._descendantAddedConnection == nil or
										self._hooksBySound[sound] ~= nil then
										return
									end
									local hooks = self._hooksBySound
									local hook = {}

									local function onPlayed()
										self:_OnPlayed(sound)
									end

									hook.played = sound.Played:Connect(onPlayed)

									local function onDestroying()
										self:_ForgetSound(sound)
									end

									hook.destroying = sound.Destroying:Connect(onDestroying)
									hooks[sound] = hook
								end

								function SoundEsp:_ForgetSound(sound)
									local hook = self._hooksBySound[sound]
									if hook == nil then
										return
									end
									self._hooksBySound[sound] = nil
									self._lastPlayedAt[sound] = nil
									hook.played:Disconnect()
									hook.destroying:Disconnect()
								end

								local circleHeight = 0.05

								function SoundEsp:_AcquireCircle()
									local circle = table.remove(self._circlePool)
									if circle == nil then
										circle = Instance.new("CylinderHandleAdornment")
										circle.Adornee = Workspace.Terrain
										circle.AlwaysOnTop = true
										circle.ZIndex = 5
										circle.Height = circleHeight
										circle.Angle = 360
										circle.Parent = self._adornFolder
									end
									circle.Visible = true
									return circle
								end

								function SoundEsp:_AcquireFootprint()
									local footprint = table.remove(self._footprintPool)
									if footprint == nil then
										footprint = Instance.new("BoxHandleAdornment")
										footprint.Adornee = Workspace.Terrain
										footprint.AlwaysOnTop = true
										footprint.ZIndex = 5
										footprint.Parent = self._adornFolder
									end
									footprint.Visible = true
									return footprint
								end

								local poolLimit = 32

								function SoundEsp:_RecycleEffect(effect)
									local adornment = effect.adornment
									adornment.Visible = false
									if effect.isCircle then
										if #self._circlePool < poolLimit then
											table.insert(self._circlePool, adornment)
											return
										end
									elseif #self._footprintPool < poolLimit then
										table.insert(self._footprintPool, adornment)
										return
									end
									adornment:Destroy()
								end

								local maxEffects = 96

								function SoundEsp._PushEffect(self_, effect)
									local effects = self_._activeEffects
									if maxEffects <= #effects then
										local oldest = table.remove(effects, 1)
										if oldest ~= nil then
											self_:_RecycleEffect(oldest)
										end
									end
									table.insert(effects, effect)
								end

								local ringWidth = 0.15
								local startTransparency = 0.2

								function SoundEsp:PreRender(deltaTime)
									local effects = self._activeEffects
									if #effects == 0 then
										return
									end
									local index = #effects - -1
									while true do
										index = index + -1
										if not (1 <= index) then
											break
										end
										local effect = effects[index]
										effect.elapsed = effect.elapsed + deltaTime
										local progress = math.clamp(effect.elapsed / effect.duration, 0, 1)
										if effect.isCircle then
											local adornment = effect.adornment
											local radius = effect.maxRadius * easeOutQuint(progress)
											adornment.Radius = radius
											adornment.InnerRadius = math.max(0, radius - ringWidth)
											adornment.Transparency = startTransparency + (1 - startTransparency) * progress ^ 4
										else
											effect.adornment.Transparency = startTransparency + (1 - startTransparency) * (progress * progress)
										end
										if 1 <= progress then
											self:_RecycleEffect(effect)
											table.remove(effects, index)
										end
									end
								end

								local circleTransparency = 0.2

								function SoundEsp:_SpawnCircle(cframe, color, duration, maxRadius)
									local circle = self:_AcquireCircle()
									circle.Color3 = color
									circle.Transparency = circleTransparency
									circle.Radius = 0.01
									circle.InnerRadius = 0
									circle.CFrame = cframe * CFrame.Angles(math.pi / 2, 0, 0)
									local pushEffect = self._PushEffect
									local effect = {
										adornment = circle,
										isCircle = true,
										elapsed = 0,
										duration = duration,
										maxRadius = maxRadius
									}
									pushEffect(self, effect)
								end

								local footprintTransparency = 0.2

								function SoundEsp:_SpawnFootprint(cframe, size, color, duration)
									local footprint = self:_AcquireFootprint()
									footprint.Size = size
									footprint.Color3 = color
									footprint.Transparency = footprintTransparency
									footprint.CFrame = cframe
									local pushEffect = self._PushEffect
									local effect = {
										adornment = footprint,
										isCircle = false,
										elapsed = 0,
										duration = duration,
										maxRadius = 0
									}
									pushEffect(self, effect)
								end

								function SoundEsp:_PassesSourceFilter(filter, model)
									if filter == "All" or model == nil then
										return true
									end
									local isSelf
									isSelf = model == LocalPlayer.Character
									if filter == "Self" then
										return isSelf
									end
									if isSelf then
										return false
									end
									local fighter = self._fighters.byModel[model]
									if fighter ~= nil then
										if filter == "Enemies" and not fighter.isEnemy then
											return false
										end
										if filter == "Team" and fighter.isEnemy then
											return false
										end
									end
									return true
								end

								local radiusPadding = 0.3
								local footprintPadding = 0.1
								local footprintHeight = 0.15

								function SoundEsp:_SpawnVisuals(mode, part, footParts, color, duration)
									local hasFeet
									hasFeet = 0 < #footParts
									if mode == "Circle" then
										if hasFeet then
											local index = nil
											while true do
												local foot
												index, foot = footParts(nil, index)
												if index == nil then
													break
												end
												local footSize = math.max(foot.Size.X, foot.Size.Z)
												self:_SpawnCircle(
													groundCFrame(foot),
													color,
													duration,
													footSize * 0.5 + radiusPadding
												)
											end
										else
											local partSize = math.max(part.Size.X, part.Size.Z)
											self:_SpawnCircle(
												groundCFrame(part),
												color,
												duration,
												partSize * 0.5 + radiusPadding
											)
										end
										return
									end
									local size
									if hasFeet then
										local index2 = nil
										while true do
											local foot2
											index2, foot2 = footParts(nil, index2)
											if index2 == nil then
												break
											end
											local footprintBox = Vector3.new(
												foot2.Size.X + footprintPadding,
												footprintHeight,
												foot2.Size.Z + footprintPadding
											)
											self:_SpawnFootprint(groundCFrame(foot2), footprintBox, color, duration)
										end
									else
										size = 0 < part.Size.Magnitude
										size = size and part.Size or footprintSize
										self:_SpawnFootprint(groundCFrame(part), size, color, duration)
									end
								end

								local replayCooldown = 0.15
								local minDuration = 0.6
								local maxDuration = 2.5

								function SoundEsp:_OnPlayed(sound)
									if sound.Volume <= 0 then
										return
									end
									local now = os.clock()
									local lastPlayed = self._lastPlayedAt[sound]
									if not (lastPlayed == nil or not (now - lastPlayed < replayCooldown)) then
										return
									end
									self._lastPlayedAt[sound] = now
									local part = getSoundPart(sound)
									if part == nil then
										return
									end
									local camera = Workspace.CurrentCamera
									if camera == nil then
										return
									end
									local distance = (camera.CFrame.Position - part.Position).Magnitude
									local maxDistance = sound.RollOffMaxDistance
									if 0 < maxDistance and
										maxDistance < distance then
										return
									end
									local settings = Config.data.SoundVisualizer
									if 0 < settings.MinVolume and
										sound.Volume < settings.MinVolume then
										return
									end
									local model = part:FindFirstAncestorOfClass("Model")
									if not self:_PassesSourceFilter(
										settings.Source,
										model
									) then
										return
									end
									local falloff
									falloff = 0 < maxDistance
									falloff = falloff and
										1 - math.clamp(distance / maxDistance, 0, 1) or 1
									local loudness = math.clamp(sound.Volume * falloff, 0, 1)
									local baseDuration = minDuration
									local extraDuration = (maxDuration - minDuration) * loudness
									local footParts
									footParts = not (model == nil)
									footParts = footParts and getFootParts(model) or {}
									local typeSettings
									typeSettings = 0 < #footParts
									local soundType
									soundType = typeSettings and "Footsteps" or typeSettings
									if not soundType then
										soundType = "Other"
									end
									if not settings.Types[soundType] then
										return
									end
									typeSettings = typeSettings and settings.Footsteps or settings.Other
									local color = typeSettings.UseLoudnessColor
									color = color and loudnessColor(loudness) or typeSettings.Color
									self:_SpawnVisuals(
										typeSettings.Mode,
										part,
										footParts,
										color,
										baseDuration + extraDuration
									)
								end

								function SoundEsp:Destroy()
									self:_StopTracking()
									self._trove:Destroy()
								end

								return SoundEsp
							end

