								local function startShooting(context)
									local inner = context.fighterState.inner
									call(inner.Input, inner, "StartShooting")
								end

								local Triggerbot = {}
								Triggerbot.__index = Triggerbot

								function Triggerbot.new(playerContext, fighters, worldInclude)
									local triggerbot = {
										_trove = Trove.new("triggerbot"),
										_playerContext = playerContext,
										_fighters = fighters,
										_worldInclude = worldInclude,
										_reactionElapsed = nil,
										_releaseRemaining = 0
									}
									return (setmetatable(triggerbot, Triggerbot))
								end

								function Triggerbot:Destroy()
									self._trove:Destroy()
								end

								function Triggerbot:ResetFiringState()
									self._reactionElapsed = nil
									self._releaseRemaining = 0
								end

								function Triggerbot:ShouldRun(config)
									local shouldRun
									shouldRun = not (config.Enabled == false)
									if shouldRun then
										shouldRun = not (config.Keybind.State == false)
									end
									return shouldRun
								end

								function Triggerbot:_CheckCrosshair(settings)
									local camera = Workspace.CurrentCamera
									local viewportSize = camera.ViewportSize
									local ray = camera:ViewportPointToRay(
										viewportSize.X / 2,
										viewportSize.Y / 2
									)
									local profile = TargetProfiles.GetProfileForContext(self._playerContext)
									local raycastParams = TargetProfiles.HasExclusions(profile)
									raycastParams = raycastParams and
										self._worldInclude:GetParamsExcluding(profile.ExcludedParts) or
										self._worldInclude:GetParams()
									local hit = Workspace:Raycast(
										ray.Origin,
										ray.Direction * 2000,
										raycastParams
									)
									if hit == nil then
										return false
									end
									local model = hit.Instance:FindFirstAncestorOfClass("Model")
									if model == nil then
										return false
									end
									local enemy = self._fighters.byModel[model]
									if enemy == nil or not enemy.isEnemy or enemy:IsInvincible() then
										return false
									end
									local state = enemy.character.state
									if not state.alive then
										return false
									end
									local targetParts
									targetParts = state.humanoid:GetState() == Enum.HumanoidStateType.Freefall
									targetParts = targetParts and settings.TargetParts.Air or
										settings.TargetParts.Ground
									if TargetProfiles.ResolveEffectiveParts(targetParts, profile)[hit.Instance.Name] ~= true then
										return false
									end
									if settings.NotDeflecting or settings.NotShielded then
										local shooterOrigin = Protection.shooterOrigin(self._playerContext)
										if not (shooterOrigin == nil or
											not Protection.isProtected(
												enemy,
												shooterOrigin,
												settings.NotDeflecting,
												settings.NotShielded
											)) then
											return false
										end
									end
									return true
								end

								function Triggerbot:Update(dt)
									local config = Config.data.Triggerbot
									if not self:ShouldRun(config) then
										self:ResetFiringState()
										return
									end
									if FireLock(
										self._playerContext,
										config.DisableOnReload,
										config.ActivateOnScope
									) then
										return
									end
									local inner = self._playerContext.inner
									if inner == nil or
										not inner.itemBehaviors:HasEquippedGun() then
										self:ResetFiringState()
										return
									end
									local onTarget = self:_CheckCrosshair(config)
									if onTarget then
										local elapsed = self._reactionElapsed
										if not elapsed then
											elapsed = 0
										end
										self._reactionElapsed = elapsed + dt
									else
										self._reactionElapsed = nil
									end
									local reacted
									reacted = not (self._reactionElapsed == nil)
									if reacted then
										reacted = config.ReactionTime <= self._reactionElapsed
									end
									if onTarget and reacted then
										self._releaseRemaining = config.ReleaseTime
										startShooting(inner)
										return
									end
									self._releaseRemaining = math.max(0, self._releaseRemaining - dt)
									if 0 < self._releaseRemaining then
										startShooting(inner)
									end
								end

								return Triggerbot
							end

