									end

									self._ensuredChildren:Observe(self._trove, setupGuard, removeEffectGuard)
								end

								function SkyController:_Reconcile()
									local preset = nil
									if Config:Get(enabledPath) then
										preset = self._skyboxes:GetPreset(Config:Get(presetPath))
									end
