								function SkyController:_SetupGuard(lighting)
									local guard = PropertyGuard.new(lighting)
									if Config:Get(enabledPath) then
										local preset = self._skyboxes:GetPreset(Config:Get(presetPath))
										if preset ~= nil then
											applyPreset(guard, preset)
										end
