									table.create(2)
									local index = nil
									while true do
										local path
										index, path = rebuildPaths(nil, index)
										if index == nil then
											break
										end
										trove:Connect(Config:GetPropertyChangedSignal(path), rebuild)
									end
									local reconcilePaths = table.create(10)
									table.create(2)
									table.create(2)
									table.create(2)
									table.create(2)
									table.create(3)
									table.create(3)
									table.create(2)
									table.create(2)
