								modules.a7()
								modules.aC()
								local settings = modules.y()
								modules.d1()
								modules.bz()
								local remoteCodec = modules.aU()
								modules.eQ()
								local notifications = modules.O()
								modules.a4()
								local RecordingPersistence = modules.gm()
								local MotionRecorder = modules.go()
								local MotionReplayer = modules.gq()
								modules.bD()
								modules.t()
								modules.gk()
								local Trove = modules.q()
								local Waypoints = modules.gt()
								local recordStatePath = table.create(4)
								local replayStatePath = table.create(4)

								local function notify(title, message)
									if not settings.data.MovementRecorder.HideNotifications then
										notifications.Get():Notify(title, message)
									end
								end

								local MovementRecorder = {}
								MovementRecorder.__index = MovementRecorder

								function MovementRecorder.new(playerContext, duelers, currentMap, cameraDirector, inputHook, replicateBinding)
									local trove = Trove.new("movement_recorder")
									local persistence = RecordingPersistence.new()
									local recorder = {
										_trove = trove,
										_playerContext = playerContext,
										_duelers = duelers,
										_currentMap = currentMap,
										_persistence = persistence,
										_cameraDirector = cameraDirector,
										_inputHook = inputHook
									}
									local idleState = { kind = "Idle" }
									recorder._state = idleState
									recorder._waypoints = nil
									recorder._lastRecording = nil
									recorder._aliveState = nil
									recorder._replicateBinding = replicateBinding
									recorder._roundActive = false
									recorder._pendingStart = nil
									recorder.recordingsChanged = persistence.reloaded
									setmetatable(recorder, MovementRecorder)
									recorder:_Initialize(trove, playerContext)
									return recorder
								end

								function MovementRecorder:_Initialize(trove, contexts)
									self:_SetupWaypointsCreation(trove, contexts)
									self:_SetupRoundTracking(trove)

									local function bindStartToggle_proto(_, noun, startAnytime, tryStart, stop)
										local statePath = table.create(4)

										local function onStartToggleChanged_proto(enabled)
											if not enabled then
												if not (self._pendingStart == nil or
													self._pendingStart.statePath ~= statePath) then
													self._pendingStart = nil
												end
												stop()
												return
											end
											if not settings.data.MovementRecorder.Enabled then
												local function turnOffToggle()
													settings:Set(statePath, false)
												end

												task.defer(turnOffToggle)
												return
											end
											if startAnytime or self:_IsRoundActive() then
												if not tryStart() then
													local function turnOffToggle2()
														settings:Set(statePath, false)
													end

													task.defer(turnOffToggle2)
												end
												return
											end
											if not self:_IsInMatch() then
												notify("You need to be in a match")

												local function turnOffToggle3()
													settings:Set(statePath, false)
												end

												task.defer(turnOffToggle3)
												return
											end
											local pending = { noun = noun, statePath = statePath, tryStart = tryStart }
											self._pendingStart = pending
											local notify2 = notify
											string.format(
												"%s will start when the round begins",
												tostring(noun)
											)
											notify2()
										end

										trove:Connect(settings:GetPropertyChangedSignal(statePath), onStartToggleChanged_proto)
									end

									local function startRecording()
										return (self:_StartRecording())
									end

									local function stopRecording()
										self:_StopRecording()
									end

									bindStartToggle_proto("Record", "Recording", false, startRecording, stopRecording)

									local function startReplayingSelected()
										local waypoints = self._waypoints
										if waypoints == nil then
											return false
										end
										local selected = waypoints:GetSelectedRecording()
										if selected == nil then
											return false
										end
										return (self:_StartReplaying(selected))
									end

									local function stopReplaying()
										self:_StopReplaying()
									end

									bindStartToggle_proto("Replay", "Replay", true, startReplayingSelected, stopReplaying)

									local function onContext(context, contextTrove)
										local character = context.fighterState.character

										local function onCharacterCreated(state)
											self._aliveState = state
										end

										contextTrove:Connect(character.created, onCharacterCreated)

										local function onDied()
											self._aliveState = nil
											self:_Reset(true)
										end

										contextTrove:Connect(character.died, onDied)
										local currentState = character.state
										if currentState.alive then
											self._aliveState = currentState
										end
									end

									trove:Add(contexts:ObserveContext("movement_recorder.ObserveContext", onContext))

									local function onContextRemoved()
										self._aliveState = nil
										self:_Reset()
									end

									trove:Connect(contexts.contextRemoved, onContextRemoved)
								end

								local RoundStarted4 = "RoundStarted"

								function MovementRecorder:_SetupRoundTracking(trove)
									local statusCode = remoteCodec.encode("Status")

									local function onStatusRemote_proto(call)
										if call.args[1] ~= statusCode then
											return
										end
										local active
										active = call.args[2] == RoundStarted4
										local wasActive = self._roundActive
										self._roundActive = active
										if active and not wasActive then
											self:_OnRoundActivated()
										end
									end

									self._replicateBinding:SetHandler(onStatusRemote_proto)
									self._replicateBinding:SetEnabled(true)
									trove:Add(self._replicateBinding)
								end

								function MovementRecorder:_IsInMatch()
									local localState = self._duelers.localState
									local inMatch
									inMatch = not (localState == nil)
									if inMatch then
										inMatch = not (localState:GetMapName() == nil)
									end
									if inMatch then
										inMatch = not (self._currentMap:GetAnchor() == nil)
									end
									return inMatch
								end

								function MovementRecorder:_IsRoundActive()
									if self._roundActive then
										return true
									end
									local localState = self._duelers.localState
									local active
									active = not (localState == nil)
									if active then
										active = localState:IsRoundActive()
									end
									return active
								end

								function MovementRecorder:_OnRoundActivated()
									if self._pendingStart == nil then
										return
									end

									local function startPending()
										local pending = self._pendingStart
										if pending == nil then
											return
										end
										self._pendingStart = nil
										if not pending.tryStart() then
											settings:Set(pending.statePath, false)
										end
									end

									task.defer(startPending)
								end

								function MovementRecorder:_ClearPending()
									local pending = self._pendingStart
									if pending == nil then
										return
									end
									self._pendingStart = nil
									settings:Set(pending.statePath, false)
								end

								function MovementRecorder:_SetupWaypointsCreation(trove, contexts)
									local function destroyWaypoints()
										local waypoints = self._waypoints
										if waypoints ~= nil then
											self._waypoints = nil
											waypoints:Destroy()
										end
									end

									local function refreshWaypoints_proto()
										if not settings.data.MovementRecorder.Enabled then
											destroyWaypoints()
											return
										end
										local anchor = self._currentMap:GetAnchor()
										if anchor == nil then
											destroyWaypoints()
											return
										end
										local localState = self._duelers.localState
										if localState == nil then
											destroyWaypoints()
											return
										end
										local mapName = localState:GetMapName()
										if mapName == nil then
											destroyWaypoints()
											return
										end
										if self._waypoints == nil then
											self._waypoints = Waypoints.new(
												self._persistence,
												contexts,
												mapName,
												anchor
											)
										end
									end

									local mapTrove = trove:Extend()

									local function onMapChanged()
										destroyWaypoints()
										refreshWaypoints_proto()
									end

									local function watchMapChanges(localState)
										mapTrove:Clean()
										mapTrove:Connect(localState.mapChanged, onMapChanged)
									end

									local function onLocalStateSet(localState)
										watchMapChanges(localState)
										refreshWaypoints_proto()
									end

									trove:Connect(self._duelers.onLocalStateSet, onLocalStateSet)

									local function onLocalStateRemoved()
										mapTrove:Clean()
										destroyWaypoints()
									end

									trove:Connect(self._duelers.onLocalStateRemoved, onLocalStateRemoved)
									local existingLocalState = self._duelers.localState
									if existingLocalState ~= nil then
										watchMapChanges(existingLocalState)
									end
									trove:Connect(self._currentMap.mapResolved, refreshWaypoints_proto)
									trove:Connect(self._currentMap.mapRemoved, destroyWaypoints)
									trove:Connect(
										settings:GetPropertyChangedSignal((table.create(2))),
										refreshWaypoints_proto
									)
									refreshWaypoints_proto()
								end

								function MovementRecorder:_ResolveStartContext()
									local aliveState = self._aliveState
									local localState = self._duelers.localState
									local inner = self._playerContext.inner
									local anchor = self._currentMap:GetAnchor()
									if aliveState == nil or localState == nil or
										(inner == nil or anchor == nil) then
										notify("You need to be alive and in a match")
										return nil
									end
									local context = {
										aliveState = aliveState,
										duelState = localState,
										innerContext = inner,
										mapAnchor = anchor
									}
									return context
								end

								function MovementRecorder:_StartRecording()
									local startContext = self:_ResolveStartContext()
									if startContext == nil then
										return false
									end
									local mapName = startContext.duelState:GetMapName()
									if mapName == nil then
										notify("You need to be alive and in a match")
										return false
									end
									local kind = self._state.kind
									if kind ~= "Idle" then
										if kind == "Recording" then
											notify("Already recording")
										elseif kind == "Replaying" then
											notify("Can't record while replaying")
										end
										return false
									end
									local inputReservation = self._inputHook:Reserve()
									local motionRecorder = MotionRecorder.new(
										mapName,
										startContext.mapAnchor,
										startContext.aliveState,
										startContext.innerContext.fighterState.inner,
										startContext.innerContext.itemBehaviors,
										inputReservation
									)
									motionRecorder:Update()
									local recordingState = { kind = "Recording", recorder = motionRecorder }
									self._state = recordingState
									notify("Now recording")
									return true
								end

								function MovementRecorder:_TeardownRecording()
									local state = self._state
									if state.kind ~= "Recording" then
										return
									end
									state.recorder:Destroy()
									local idleState = { kind = "Idle" }
									self._state = idleState
								end

								function MovementRecorder:_StopRecording()
									local state = self._state
									if state.kind ~= "Recording" then
										return
									end
									self._lastRecording = state.recorder:GetRecording()
									self:_TeardownRecording()
									notify("Recording stopped")
								end

								function MovementRecorder:_StartReplaying(recording)
									local startContext = self:_ResolveStartContext()
									if startContext == nil then
										return false
									end
									local kind = self._state.kind
									if kind ~= "Idle" then
										if kind == "Recording" then
											notify("Can't replay while recording")
										elseif kind == "Replaying" then
											notify("Already replaying")
										end
										return false
									end
									local waypoints = self._waypoints
									if waypoints ~= nil then
										waypoints:SetActivatedRecording(recording)
									end

									local function isRoundActive()
										return (self:_IsRoundActive())
									end

									local function onReplayFinished(reason)
										self:_FinishReplaying(reason)
									end

									local replayer = MotionReplayer.new(
										startContext.aliveState,
										startContext.innerContext.fighterState.inner,
										startContext.innerContext.itemBehaviors,
										startContext.mapAnchor,
										recording,
										self._cameraDirector,
										isRoundActive,
										onReplayFinished
									)
									local replayingState = { kind = "Replaying", replayer = replayer }
									self._state = replayingState
									notify("Now replaying")
									return true
								end

								function MovementRecorder:_TeardownReplay()
									local state = self._state
									if state.kind ~= "Replaying" then
										return
									end
									state.replayer:Destroy()
									local idleState = { kind = "Idle" }
									self._state = idleState
									local waypoints = self._waypoints
									if waypoints ~= nil then
										waypoints:SetActivatedRecording(nil)
									end
								end

								function MovementRecorder:_StopReplaying()
									if self._state.kind ~= "Replaying" then
										return
									end
									self:_TeardownReplay()
									notify("Stopped replaying")
								end

								function MovementRecorder:_FinishReplaying(reason)
									if self._state.kind ~= "Replaying" then
										return
									end
									self:_TeardownReplay()
									settings:Set(replayStatePath, false)
									if reason == "Diverged" then
										notify("Replay stopped (off course)")
									else
										notify("Finished replaying")
									end
								end

								function MovementRecorder:_Reset(notify2)
									self:_ClearPending()
									local kind = self._state.kind
									if kind == "Idle" then
										return
									end
									if kind == "Recording" then
										self:_TeardownRecording()
										settings:Set(recordStatePath, false)
										if notify2 then
											notify("Recording stopped")
										end
									else
										self:_TeardownReplay()
										settings:Set(replayStatePath, false)
										if notify2 then
											notify("Stopped replaying")
										end
									end
								end

								function MovementRecorder:SaveRecording(name)
									local lastRecording = self._lastRecording
									if lastRecording == nil then
										notify("No recording to save")
										return
									end
									if not self._persistence:Save(name, lastRecording).ok then
										notify("Failed to save recording")
										return
									end
									self._lastRecording = nil
									notify("Recording saved")
								end

								function MovementRecorder:GetRecordingMaps()
									return (self._persistence:GetMaps())
								end

								function MovementRecorder:GetRecordingNames(mapName)
									return (self._persistence:GetNamesForMap(mapName))
								end

								function MovementRecorder:DeleteRecording(name)
									if self._persistence:Delete(name).ok then
										notify("Recording deleted")
										return
									end
									notify("Failed to delete recording")
								end

								function MovementRecorder:Update(dt)
									local state = self._state
									if state.kind == "Recording" then
										state.recorder:Update()
									elseif state.kind == "Replaying" then
										state.replayer:Update(dt)
									end
									local waypoints = self._waypoints
									if waypoints ~= nil then
										waypoints:Update()
									end
								end

								function MovementRecorder:Destroy()
									self:_Reset()
									self._trove:Destroy()
									local waypoints = self._waypoints
									if waypoints ~= nil then
										waypoints:Destroy()
									end
								end

								return MovementRecorder
							end

