								local function bindProfileOptions(_, controls)
									local gunSpecificPath = table.create(3)
									local lastProfile = "GunSpecific"

									local function getEditProfile()
										if Config:Get(gunSpecificPath, true) == false then
											return nil
										end
										return (Config:GetEditProfile())
									end

									lastProfile = nil

									local function refresh()
										local editProfile = getEditProfile()
										local profile = TargetProfiles.GetProfile(editProfile)
										if profile ~= lastProfile then
											lastProfile = profile
											local controlList = controls
											local index = nil
											while true do
												local control
												index, control = controlList(nil, index)
												if index == nil then
													break
												end
												control.dropdown:SetOptions(profile.AvailableOptions)
											end
										end
									end

									local index2 = nil
									while true do
										local control2
										index2, control2 = controls(nil, index2)
										if index2 == nil then
											break
										end
										control2.dropdown:Connect(Config.editProfileChanged, refresh)
										control2.dropdown:Connect(Config:GetPropertyChangedSignal(gunSpecificPath), refresh)
									end
									refresh()
								end

								return bindProfileOptions
							end

