								local general = "General"

								local function build(section, weapon, profiles, weapons)
									local enabledPath = table.create(3)
									local addToggle = section.AddToggle
-- [removed 1 line(s) containing unnamed identifiers]
									local toggle = addToggle(section, toggleOptions)
									toggle:Set(profiles:Get(enabledPath), true)

									local function onToggleChanged(value)
										profiles:Set(enabledPath, value)
									end

									toggle:Connect(toggle.Changed, onToggleChanged)

									local function onConfigChanged(value)
										if toggle.Value ~= value then
											toggle:Set(value, true)
										end
									end

									toggle:Connect(profiles:GetPropertyChangedSignal(enabledPath), onConfigChanged)
									local profileOptions = concat(table.create(1), weapons.allWeapons)
									local addDropdown = section.AddDropdown
									local dropdownOptions = { Row = toggle.Row, Options = profileOptions }
									local profileDropdown = addDropdown(section, dropdownOptions)
									local addToggle2 = section.AddToggle
									local activeToggleOptions = { Label = "Active" }
									local activeToggle = addToggle2(section, activeToggleOptions)

									local function syncActive(profile)
										local active
										active = not (profile == nil)
										if active then
											active = profiles:IsProfileActive(profile, weapon)
										end
										if activeToggle.Value ~= active then
											activeToggle:Set(active, true)
										end
									end

									local function onProfileChanged(profile)
										if profile == general then
											profiles:SetEditProfile(nil)
										else
											profiles:SetEditProfile(profile)
										end
									end

									profileDropdown:Connect(profileDropdown.Changed, onProfileChanged)

									local function onActiveChanged(active)
										if profiles:GetEditProfile() == nil then
											activeToggle:Set(false, true)
											return
										end
										profiles:Set(table.create(4), active)
									end

									activeToggle:Connect(activeToggle.Changed, onActiveChanged)

									local function onEditProfileChanged()
										local profile = profiles:GetEditProfile()
										if not profile then
											profile = general
										end
										if profileDropdown.Value ~= profile then
											profileDropdown:Set(profile, true)
										end
										syncActive(profile)
									end

									toggle:Connect(profiles.editProfileChanged, onEditProfileChanged)
									onEditProfileChanged()
								end

								return build
							end

