								function PlayerEsp:_Refresh()
									local esp = Config.data.ESP
									local settings
									settings = self._faction == "Team"
									settings = settings and esp.Team or esp.Enemy
									local shared = esp.Settings
									local font = Fonts:Get(shared.Font)
									local flagFont = Fonts:Get(shared.FlagFont)
									local fontSize = shared.FontSize
									local flagFontSize = shared.FlagFontSize
									local spacing = shared.Spacing
									local sideFrames = self._sideFrames
									local index = nil
									while true do
										local side
										index, side = sideFrames(nil, index)
										if index == nil then
											break
										end
										side.frame.Position = panePosition(side.preset, spacing[side.key])
									end
									local boundingBox = self._boundingBox
									local box = settings.Box
									local boxImage = settings.BoxImage
									local showImage = boxImage.Enabled
									if showImage then
										showImage = not (boxImage.Path == "")
									end
									if box.Enabled or showImage then
										if box.Enabled then
											boundingBox:SetStyle(box.Style)
											boundingBox:ToggleOutline(true)
											boundingBox:SetInnerLook(
												box.Color,
												LookKinds.resolve(box.Animation)
											)
											local filledBox = settings.FilledBox
											if filledBox.Enabled then
												local gradient = filledBox.Gradient
												if gradient.Enabled then
													local setFillLook = boundingBox.SetFillLook
													local color = gradient.Color
													local transparency = filledBox.Transparency
													local animation = gradient.Animate
													if animation then
														animation = true
													end
													animation = animation and "Swirl" or nil
													setFillLook(boundingBox, color, transparency, animation)
												else
													boundingBox:SetFillLook(
														filledBox.Color,
														filledBox.Transparency,
														nil
													)
												end
												boundingBox:ToggleFill(true)
											else
												boundingBox:ToggleFill(false)
											end
										else
											boundingBox:ToggleOutline(false)
											boundingBox:ToggleFill(false)
										end
										if showImage then
											boundingBox:SetImage(boxImage.Path)
											boundingBox:SetImageLook(boxImage.Transparency)
											boundingBox:ToggleImage(true)
										else
											boundingBox:ToggleImage(false)
										end
										boundingBox:SetVisible(true)
									else
										boundingBox:ToggleOutline(false)
										boundingBox:ToggleFill(false)
										boundingBox:ToggleImage(false)
										boundingBox:SetVisible(false)
									end
									local nameLabel = self._nameLabel
									if settings.Name.Enabled then
										nameLabel:SetFont(font)
										nameLabel:SetLook(
											settings.Name.Color,
											fontSize,
											settings.Name.Transparency,
											LookKinds.resolve(settings.Name.Animation)
										)
										nameLabel:SetText("Player")
										nameLabel:SetVisible(true)
									else
										nameLabel:SetVisible(false)
									end
									local distanceLabel = self._distanceLabel
									if settings.Distance.Enabled then
										distanceLabel:SetFont(font)
										distanceLabel:SetLook(
											settings.Distance.Color,
											fontSize,
											nil,
											LookKinds.resolve(settings.Distance.Animation)
										)
										distanceLabel:SetText("42m")
										distanceLabel:SetVisible(true)
									else
										distanceLabel:SetVisible(false)
									end
									local heldWeaponLabel = self._heldWeaponLabel
									if settings.HeldWeapon.Enabled then
										heldWeaponLabel:SetFont(font)
										heldWeaponLabel:SetLook(
											settings.HeldWeapon.Color,
											fontSize,
											settings.HeldWeapon.Transparency,
											LookKinds.resolve(settings.HeldWeapon.Animation)
										)
										heldWeaponLabel:SetText("Assault Rifle")
										heldWeaponLabel:SetVisible(true)
									else
										heldWeaponLabel:SetVisible(false)
									end
									local rankLabel = self._rankLabel
									if settings.Rank.Enabled then
										rankLabel:SetFont(flagFont)
										rankLabel:SetLook(
											settings.Rank.Color,
											flagFontSize,
											nil,
											LookKinds.resolve(settings.Rank.Animation)
										)
										rankLabel:SetText("Diamond")
										rankLabel:SetVisible(true)
									else
										rankLabel:SetVisible(false)
									end
									local winstreakLabel = self._winstreakLabel
									if settings.Winstreak.Enabled then
										winstreakLabel:SetFont(flagFont)
										winstreakLabel:SetLook(
											settings.Winstreak.Color,
											flagFontSize,
											nil,
											LookKinds.resolve(settings.Winstreak.Animation)
										)
										winstreakLabel:SetText("5 WS")
										winstreakLabel:SetVisible(true)
									else
										winstreakLabel:SetVisible(false)
									end
									local deflectingLabel = self._deflectingLabel
									if settings.Deflecting.Enabled then
										deflectingLabel:SetFont(flagFont)
										deflectingLabel:SetLook(
											settings.Deflecting.Color,
											flagFontSize,
											settings.Deflecting.Transparency,
											LookKinds.resolve(settings.Deflecting.Animation)
										)
										deflectingLabel:SetText("DEFLECTING")
										deflectingLabel:SetVisible(true)
									else
										deflectingLabel:SetVisible(false)
									end
									local healthBar = self._healthBar
									local healthSettings = settings.HealthBar
									if healthSettings.Enabled then
										healthBar:SetColor(healthSettings.Color, healthSettings.ColorMode)
										healthBar:SetFont(font)
										healthBar:SetLabelColor(settings.HealthNumber.Color)
										local animateBar = healthBar.AnimateBar
										local animate = healthSettings.Animate
										if animate then
											animate = true
										end
										animateBar(healthBar, animate)
										healthBar:SetValue(75, 100)
										healthBar:SetLabelVisible(settings.HealthNumber.Enabled)
										healthBar:SetVisible(true)
									else
										healthBar:SetVisible(false)
									end
									local ammoBar = self._ammoBar
									local ammoSettings = settings.AmmoBar
									if ammoSettings.Enabled then
										ammoBar:SetColor(ammoSettings.Color, ammoSettings.ColorMode)
										ammoBar:SetFont(font)
										local animateBar2 = ammoBar.AnimateBar
										local animate2 = ammoSettings.Animate
										if animate2 then
											animate2 = true
										end
										animateBar2(ammoBar, animate2)
										ammoBar:SetValue(20, 30)
										ammoBar:SetLabelVisible(false)
										ammoBar:SetVisible(true)
									else
										ammoBar:SetVisible(false)
									end
								end

								return PlayerEsp
							end

