								local EspPreview = modules.gX()
								modules.cI()
								local buildFactionSections = modules.g0()
								local addKeybindToggle = modules.gP()
								local RootTrove = modules.r()
								local Players = cloneref(game:GetService("Players"))
								local previewUserId = 1

								local function createPreviewModel()
									local function getDescription()
										return (Players:GetHumanoidDescriptionFromUserIdAsync(previewUserId))
									end

									local description, ok
-- [removed 1 line(s) containing unnamed identifiers]
									if not (ok and description ~= nil) then
										return nil
									end

									local function createModel()
										return (Players:CreateHumanoidModelFromDescriptionAsync(description, Enum.HumanoidRigType.R15))
									end

									local model, ok2
-- [removed 1 line(s) containing unnamed identifiers]
									if not (ok2 and model ~= nil) then
										return nil
									end
									model:PivotTo(CFrame.identity)
									local animate = model:FindFirstChild("Animate")
									if animate ~= nil then
										animate:Destroy()
									end
									return model
								end

								local previewHeight = 400

								local function buildEspTab(tab, deps)
									local addSection = tab.AddSection
									local mainOptions = { Title = "Main", Side = "left" }
									local mainSection = addSection(tab, mainOptions)
									local addMultiSection = tab.AddMultiSection
									local multiSectionOptions = {}
									local temp = "Enemy"
									multiSectionOptions.Titles = table.create(2)
									multiSectionOptions.Side = "left"
									local teamPage, enemyPage
									enemyPage, teamPage = addMultiSection(tab, multiSectionOptions)
									local addSection2 = tab.AddSection
									temp = { Title = "Preview", Side = "right" }
									local previewSection = addSection2(tab, temp)
									temp = mainSection
									addKeybindToggle(
										temp,
-- [removed 1 line(s) containing unnamed identifiers]
										table.create(2),
										table.create(2),
										true,
										"ESP"
									)
									temp = mainSection
									local addDropdown = mainSection.AddDropdown
									local modeDropdownOptions = {
										Label = "Mode",
										Options = table.create(2),
										Config = table.create(3)
									}
									addDropdown(temp, modeDropdownOptions)
									temp = previewSection
									local addViewport = previewSection.AddViewport
									local viewportOptions = {
										Height = previewHeight,
										AutoRotate = true,
										RotateSpeed = 0.45,
										FieldOfView = 18,
										DistanceMul = 4
									}
									local viewport = addViewport(temp, viewportOptions)
									temp = nil

									local function onViewportRealized(viewportFrame)
										local previewEsp = EspPreview.new(deps, viewportFrame)
										RootTrove:Add(previewEsp)
										previewEsp:SetFaction("Enemy")
										temp = previewEsp

										local function loadPreviewModel(...)
											local model = createPreviewModel()
											if model == nil then
												return
											end
											viewport:SetModel(model)
											viewport:SetRotation(math.rad(225))
											model:Destroy()
										end

										task.spawn(loadPreviewModel)
									end

									viewport:OnRealized(onViewportRealized)

									local function followPage(page, faction)
										local function onOpened(opened)
											if opened and temp ~= nil then
												temp:SetFaction(faction)
											end
										end

										page.Opened:Connect(onOpened)
									end

									followPage(teamPage, "Team")
									followPage(enemyPage, "Enemy")
									buildFactionSections(teamPage, "Team")
									buildFactionSections(enemyPage, "Enemy")
								end

								return buildEspTab
							end

