								local function buildModifierToggles(section, configPath)
									local modifiers = fields
									local index = nil
									while true do
										local modifier
										index, modifier = modifiers(nil, index)
										if index == nil then
											break
										end
										local addToggle = section.AddToggle
										local toggleOptions = { Label = modifier.label, Config = appendPath(configPath, (table.create(2))) }
										local toggle = addToggle(section, toggleOptions)
										local value = modifier.value
										if value.kind ~= "toggle" then
											local valuePath = appendPath(configPath, (table.create(2)))
											local addGroup = section.AddGroup
											local groupOptions = { Source = toggle }
											local group = addGroup(section, groupOptions)
											if value.kind == "percent" then
												local addSlider = group.AddSlider
												local sliderOptions = {
													Label = value.placeholder,
													Min = 0,
													Max = 100,
													Step = 0.1,
													Config = valuePath
												}
												addSlider(group, sliderOptions)
											elseif value.kind == "number" then
												local addTextBox = group.AddTextBox
												local textBoxOptions = { Label = value.placeholder }
												bindNumberTextBox(addTextBox(group, textBoxOptions), valuePath)
											elseif value.kind == "text" then
												local addTextBox2 = group.AddTextBox
												local textBoxOptions2 = { Label = value.placeholder, Config = valuePath }
												addTextBox2(group, textBoxOptions2)
