								local faceFields = table.create(6)

								local function buildCustomSkyboxesSection(deps, tab)
									local skyboxes = deps.skyboxes
									local addSection = tab.AddSection
									local sectionOptions = { Title = "Custom Skyboxes", Side = "right" }
									local customSkyboxesSection = addSection(tab, sectionOptions)
									local addTextBox = customSkyboxesSection.AddTextBox
									local nameTextBoxOptions = { Label = "Name" }
									local nameTextBox = addTextBox(customSkyboxesSection, nameTextBoxOptions)
									local faceTextBoxes = {}
									local faces = faceFields
									local index = nil
									while true do
										local face
										index, face = faces(nil, index)
										if index == nil then
											break
										end
										local key = face.Key
										local addTextBox2 = customSkyboxesSection.AddTextBox
										local textBoxOptions = { Label = face.Label }
										faceTextBoxes[key] = addTextBox2(customSkyboxesSection, textBoxOptions)
									end
									local addButton = customSkyboxesSection.AddButton
									local addButtonOptions = { Label = "Add" }

									function addButtonOptions.OnClick()
										local values = {}
										local fields = faceTextBoxes
										local key2 = nil
										while true do
											local field
											key2, field = fields(nil, key2)
											if key2 == nil then
												break
											end
											values[key2] = field.Value
										end
										if not skyboxes:Add(nameTextBox.Value, values).ok then
											return
										end
										nameTextBox:Set("")
										local fields2 = faceTextBoxes
										local key2_2 = nil
										while true do
											local field2
											key2_2, field2 = fields2(nil, key2_2)
											if key2_2 == nil then
												break
											end
											field2:Set("")
										end
									end

									addButton(customSkyboxesSection, addButtonOptions)
									local addDropdown = customSkyboxesSection.AddDropdown
									local savedDropdownOptions = { Label = "Saved", Options = skyboxes:GetNames(), CloseOnSelect = true }
									local savedDropdown = addDropdown(customSkyboxesSection, savedDropdownOptions)

									local function setSavedOptions(names)
										savedDropdown:SetOptions(names)
									end

									savedDropdown:Connect(skyboxes.changed, setSavedOptions)
									local addButton2 = customSkyboxesSection.AddButton
									local removeButtonOptions = { Label = "Remove" }

									function removeButtonOptions.OnClick()
										local selected = savedDropdown.Value
										if type(selected) ~= "string" then
											return
										end
										skyboxes:Remove(selected)
									end

									addButton2(customSkyboxesSection, removeButtonOptions)
								end

								return buildCustomSkyboxesSection
							end

