								local function makeNameFilter(pattern)
									if pattern == "" then
										return nil
									end

									local function matches(instance, text)
										if alwaysShown[instance.Name] then
											return true
										end
										local found
										found = not (fuzzyMatch(text, pattern) == nil)
										return found
									end

									return matches
								end

								local function buildItemList_proto(nextName, makeRenderer)
									local items = table.clone(specialItems)
									local index, renderer
									while true do
										local name
										index, name = nextName(nil, index)
										if index == nil then
											break
										end
										local _ = table.insert
										local entry = { Name = name, Image = getImage(name) }
										if makeRenderer then
											renderer = makeRenderer(name)
										else
											renderer = makeRenderer
										end
										entry.Render = renderer
										table.insert(items, entry)
									end
									return items
								end

								local previewCameraCFrame = CFrame.Angles(0, 3.490658503988659, 0) * CFrame.Angles(-0.2617993877991494, 0, 0) * CFrame.new(0, 0, 1)

								local function makeWrapPreview_proto(wrapName)
									local function renderWrapPreview(_, tile)
										tile.HideImage()
										local viewportFrame = Instance.new("ViewportFrame")
										viewportFrame.Size = UDim2.fromScale(1, 1)
										viewportFrame.Position = UDim2.fromScale(0.5, 0.5)
										viewportFrame.AnchorPoint = Vector2.new(0.5, 0.5)
										viewportFrame.BackgroundTransparency = 1
										viewportFrame.Parent = tile.Content
										local camera = Instance.new("Camera")
										camera.FieldOfView = 25
										camera.CFrame = previewCameraCFrame
										camera.Parent = viewportFrame
										viewportFrame.CurrentCamera = camera
										local model = wrapPreviewModel:Clone()
										model:PivotTo(CFrame.identity)
										local originals = wrapRenderer.recordOriginalProperties(model)
										wrapRenderer.applyWrap(originals, wrapName)
										model.Parent = viewportFrame
									end

									return renderWrapPreview
								end

								local charmPitch = -0.2617993877991494

								local function makeItemPreview(itemName)
									local function renderPreview(_, slot)
										local template = charmsFolder:FindFirstChild(itemName)
										if template == nil then
											return
										end
										slot.HideImage()
										local viewportFrame = Instance.new("ViewportFrame")
										viewportFrame.Size = UDim2.fromScale(1, 1)
										viewportFrame.Position = UDim2.fromScale(0.5, 0.5)
										viewportFrame.AnchorPoint = Vector2.new(0.5, 0.5)
										viewportFrame.BackgroundTransparency = 1
										viewportFrame.Parent = slot.Content
										local camera = Instance.new("Camera")
										camera.FieldOfView = 25
										camera.Parent = viewportFrame
										viewportFrame.CurrentCamera = camera
										local model = template:Clone()
										if model:IsA("Model") then
											local primary = model:FindFirstChild("Primary")
											if primary and primary:IsA("BasePart") then
												model.PrimaryPart = primary
											end
											model:PivotTo(CFrame.identity)
											local hook = model:FindFirstChild("Hook")
											if hook then
												hook:Destroy()
											end
										end
										model.Parent = viewportFrame
										camera.CFrame = CFrame.Angles(0, 3.62836073281, 0) * CFrame.Angles(charmPitch, 0, 0) * CFrame.new(0, 0, 0.3)
									end

									return renderPreview
								end

