								end

								function LongJump:_OnStateChanged(triggered)
									if not triggered then
										return
									end

									local function resetTrigger()
										Config:Set(triggerPath, false)
									end

									task.defer(resetTrigger)
									if not Config.data.Movement.LongJump.Enabled then
										return
									end
									self:_Launch()
