								function Flickbot.new(aimbot, playerContext, targetSelection, cameraDirector)
									local trove = Trove.new("flickbot")
									local flickbot = {
										_trove = trove,
										_aimbot = aimbot,
										_playerContext = playerContext,
										_targetSelection = targetSelection,
										_cameraDirector = cameraDirector,
										_state = "Idle",
										_trajectory = nil,
										_trajectoryIndex = 1,
										_elapsedMs = 0,
