								local riotShieldName = "Riot Shield"

								local function getRiotShieldSide(fighterState)
									local itemObserver = fighterState.itemObserver
									local equipped = itemObserver:GetEquippedItem()
									if not (equipped == nil or
										equipped.name ~= riotShieldName) then
										local pitch = math.deg(fighterState:GetCameraRotation().X)
										if 22 < pitch and pitch < 91 then
											return "Below"
										end
										return "Above"
									end
									for _, item in itemObserver:GetItems() do
										if item.name == riotShieldName then
											local pitch2 = math.deg(fighterState:GetCameraRotation().X)
											if 315 < pitch2 and pitch2 < 360 or
												0 < pitch2 and pitch2 < 91 then
												return "Above"
											end
											return "Below"
										end
									end
									return "None"
								end

								return getRiotShieldSide
							end

