										rng:NextNumber(0, 2 * math.pi),
										rng:NextNumber(0, 2 * math.pi)
									)
								end

								local pitchLimit = 90

								function DefensiveAngles.getDefensiveViewAngles(shieldState, fighterState)
									if shieldState == "None" then
										return nil
									end
									local isAbove
									isAbove = not (getRiotShieldSide(fighterState) == "Below")
									local equipped
									equipped = shieldState == "Equipped"
									local pitch
									pitch = not (equipped == isAbove)
									pitch = pitch and pitchLimit or -pitchLimit
									local angles = { kind = "Normalized", pitch = pitch, yaw = rng:NextNumber(0, 360) }
									return angles
								end

								return DefensiveAngles
